        var incomingPairwise=document.has("pairwiseSettings")&&!document.get("pairwiseSettings").isJsonNull()?new Gson().fromJson(document.get("pairwiseSettings"),PairwiseDialog.Settings.class):null;if(incomingPairwise!=null&&Arrays.stream(incomingPairwise.columns()).anyMatch(i->i>=incoming[0].length))throw new IllegalArgumentException("Pairwise selection lies outside this dataset.");
        var incomingSensitivity=SensitivityDialog.read(document.get("sensitivitySettings"));
