        var incomingAdjusted=new java.util.EnumMap<AdjustedCopulaDialog.Context,AdjustedCopulaDialog.Settings>(AdjustedCopulaDialog.Context.class);if(document.has("adjustedCopulaSettings"))for(var entry:document.getAsJsonObject("adjustedCopulaSettings").entrySet()){var context=AdjustedCopulaDialog.Context.valueOf(entry.getKey());var settings=AdjustedCopulaDialog.parse(entry.getValue().getAsJsonObject());if(settings.context()!=context)throw new IllegalArgumentException("Adjusted-copula context identity differs from its saved key.");for(int column:settings.columns())if(column>=names.size())throw new IllegalArgumentException("Saved adjusted-copula data binding is missing.");for(int column:settings.binaryBindings().values())if(column>=names.size())throw new IllegalArgumentException("Saved binary data binding is missing.");incomingAdjusted.put(context,settings);}
