    @SuppressWarnings("unchecked") private static TableView<String[]> sourceTable(Node node){if(node instanceof TableView<?> table&&!Boolean.TRUE.equals(node.getProperties().get("brightstats.presentationOnly")))return (TableView<String[]>)table;if(node instanceof BorderPane border){var found=sourceTable(border.getCenter());if(found!=null)return found;}if(node instanceof javafx.scene.Parent parent)for(Node child:parent.getChildrenUnmodifiable()){var found=sourceTable(child);if(found!=null)return found;}return null;}
    private void refreshData(){String frame=VisualSelection.frame(projectDocument());if(!frame.equals(activeSourceFrame)){visualSelection=null;linkedColumns.clear();viewLinkedData.setVisible(false);}activeSourceFrame=frame;refreshDataContent();if(visualSelection!=null)visualSelection(visualSelection);if(datasetDerivation!=null){Node content=dataTab.getContent();dataTab.setContent(null);Label warning=new Label(ProjectDerivation.WARNING);warning.setWrapText(true);warning.setPadding(new Insets(10));warning.setStyle("-fx-background-color:#fff5cf;-fx-text-fill:#613c00;");warning.setAccessibleText("Fixed exported score provenance. "+ProjectDerivation.WARNING);dataTab.setContent(new BorderPane(content,warning,null,null,null));}}
    private void refreshDataContent() {
        TableView<double[]> table = new TableView<>();linkedPreparedTable=table;linkedSourceTable=null;preparedSourceRows.clear();List<Integer> sourceMapping=importHistory==null?java.util.stream.IntStream.rangeClosed(1,data.length).boxed().toList():ImportHistory.read(importHistory).sourceRows();for(int i=0;i<data.length;i++)preparedSourceRows.put(data[i],sourceMapping.get(i));table.getSelectionModel().setSelectionMode(SelectionMode.MULTIPLE);
        for (int j = 0; j < columnNames.size(); j++) {
            int column = j; TableColumn<double[], String> item = new TableColumn<>(columnNames.get(j)); item.setPrefWidth(105);
            item.setCellValueFactory(cell -> new ReadOnlyStringWrapper(format(cell.getValue()[column])));item.setComparator(TableTools::compareCells);item.setCellFactory(ignore->new TableCell<>(){@Override protected void updateItem(String value,boolean empty){super.updateItem(value,empty);setText(empty?null:value);pseudoClassStateChanged(javafx.css.PseudoClass.getPseudoClass("linked-column"),!empty&&linkedColumns.contains(item.getText()));setTooltip(empty?null:new Tooltip(item.getText()+"\n"+value));}});
            table.getColumns().add(item);
        }
        table.getItems().addAll(Arrays.asList(data));
        List<String[]> summaries = new ArrayList<>();
        if (data.length > 0) {
            var statistics = DescriptiveStatistics.summarize(data);
            for (int j = 0; j < statistics.length; j++) {
                var value = statistics[j];
                summaries.add(new String[]{columnNames.get(j), Integer.toString(value.observed()), Integer.toString(value.missing()),
                        format(value.mean()), format(value.upperMedian()), format(value.midpointMedian()),
                        format(value.populationStandardDeviation()), format(value.minimum()), format(value.maximum())});
            }
        }
        Tab raw = new Tab("Analysis data", table);
        Tab summary = new Tab("Descriptive statistics", table(List.of("Indicator", "Observed", "Missing", "Mean",
                "Median (upper)", "Median (midpoint)", "SD (population)", "Minimum", "Maximum"), summaries));
        raw.setClosable(false); summary.setClosable(false);
        TabPane views = new TabPane(raw, summary);dataViews=views;
        if (importHistory != null) {
            var history = ImportHistory.read(importHistory);
            List<String> headers = new ArrayList<>(); headers.add("Source row");
            headers.addAll(history.definitions().stream().map(c -> c.name() + " [" + c.kind() + "]").toList());
            List<String[]> source = new ArrayList<>();
            for (int i = 0; i < history.raw().rows().size(); i++) {
                List<String> row = new ArrayList<>(); row.add(Integer.toString(i + 1)); row.addAll(history.raw().rows().get(i)); source.add(row.toArray(String[]::new));
            }
            resultTab(views, "Source data", headers, source);linkedSourceTable=sourceTable(views.getTabs().getLast().getContent());if(linkedSourceTable!=null)linkedSourceTable.getSelectionModel().setSelectionMode(SelectionMode.MULTIPLE);
            String retained = history.sourceRows().toString();
            Label description = new Label("Source: " + history.sourceName() + "\nDelimiter: "
                    + (history.settings().delimiter() == '\t' ? "Tab" : history.settings().delimiter())
                    + " · Decimal: " + history.settings().decimal() + " · Missing marker: " + history.settings().missingMarker()
                    + "\nTreatment: " + history.settings().treatment() + " · Replaced cells: " + history.replacedCells()
                    + " · Removed rows: " + history.removedRows() + "\nAnalysis rows map to source data rows (header excluded): " + retained
                    + "\n" + String.join("\n", DataPreparation.warnings(data, columnNames)));
            description.setWrapText(true); description.setPadding(new Insets(15));
            ScrollPane details = new ScrollPane(description); details.setFitToWidth(true);
            Tab preparation = new Tab("Preparation", details); preparation.setClosable(false); views.getTabs().add(preparation);
            if(importHistory.has("formatSource")){var format=importHistory.getAsJsonObject("formatSource");TabPane metadata=new TabPane();List<String[]> notices=new ArrayList<>();notices.add(new String[]{"Source format",format.get("sourceType").getAsString()});if(format.has("sheet"))notices.add(new String[]{"Worksheet",format.get("sheet").getAsString()});if(format.has("encoding"))notices.add(new String[]{"Encoding",format.get("encoding").getAsString()});if(format.has("warnings"))for(var warning:format.getAsJsonArray("warnings"))notices.add(new String[]{"Notice",warning.getAsString()});resultTab(metadata,"File details",List.of("Property","Value"),notices);if(format.has("variables")){List<String[]> variables=new ArrayList<>();for(var element:format.getAsJsonArray("variables")){var variable=element.getAsJsonObject();variables.add(new String[]{variable.get("name").getAsString(),variable.get("label").getAsString(),variable.get("measure").getAsString(),variable.get("width").getAsInt()==0?"Numeric":"Text",variable.get("valueLabels").toString(),variable.get("missingValues").toString(),variable.has("missingLow")?variable.get("missingLow").toString()+" to "+variable.get("missingHigh"):""});}resultTab(metadata,"Variable metadata",List.of("Variable","Label","Measurement level","Storage type","Value labels","Missing codes","Missing range"),variables);}if(format.has("original")){var originalSource=new Gson().fromJson(format.get("original"),DataPreparation.Raw.class);resultTab(metadata,"Original file values",originalSource.headers(),originalSource.rows().stream().map(row->row.toArray(String[]::new)).toList());}Tab formatTab=new Tab("File metadata",metadata);formatTab.setClosable(false);views.getTabs().add(formatTab);}

        }
        if(importHistory!=null&&importHistory.has("transformations")){List<String[]> transformations=new ArrayList<>();int index=0;for(var value:importHistory.getAsJsonArray("transformations")){var step=value.getAsJsonObject();var spec=step.getAsJsonObject("specification");transformations.add(new String[]{Integer.toString(++index),spec.get("operation").getAsString(),spec.get("sources").toString(),spec.get("outputs").toString(),spec.get("reference").getAsString(),spec.get("missingCategory").isJsonNull()?"Propagate missing":spec.get("missingCategory").getAsString(),"Fixed row function; original cells before preparation"});}resultTab(views,"Transformation lineage",List.of("Step","Operation","Sources","New columns","Reference","Missing category","Contract"),transformations);}
        dataTab.setContent(views);
    }
    private void addConstruct(){configureConstruct(-1);}
    private void editConstruct(int index){if(index<0||index>=constructs.size())throw new IllegalArgumentException("Select a construct first.");configureConstruct(index);}
    private void configureConstruct(int index){if(data.length==0)throw new IllegalArgumentException("Import data first.");java.util.Set<String> names=new java.util.HashSet<>();for(int i=0;i<constructs.size();i++)if(i!=index)names.add(constructs.get(i).name);Construct previous=index<0?null:constructs.get(index);var settings=previous==null?null:new ConstructDialog.Settings(previous.name,previous.columns,previous.mode,previous.initialWeights,previous.measurementType);var choice=ConstructDialog.show(stage,columnNames,names,settings);if(choice.isEmpty())return;var selectedSettings=choice.get();int next=index<0?constructs.size():index;Construct replacement=new Construct(selectedSettings.name(),selectedSettings.columns(),selectedSettings.mode(),previous==null?140+(next%3)*265:previous.x,previous==null?130+(next/3)*210:previous.y,selectedSettings.weights(),selectedSettings.measurement());if(index<0)constructs.add(replacement);else constructs.set(index,replacement);selected=next;selection.clear();selection.add(next);invalidate();}
    private void connectConstructs() {
        if (constructs.size() < 2) throw new IllegalArgumentException("Add at least two constructs first");
        Dialog<ButtonType> dialog = new Dialog<>(); dialog.setTitle("Connect constructs"); dialog.initOwner(stage);
        ComboBox<String> from = new ComboBox<>(), to = new ComboBox<>();
        for (Construct construct : constructs) { from.getItems().add(construct.name); to.getItems().add(construct.name); }
        from.getSelectionModel().select(0); to.getSelectionModel().select(1);
        dialog.getDialogPane().setContent(new VBox(10, UiAppearance.label("From"), from, UiAppearance.label("To"), to));
        dialog.getDialogPane().getButtonTypes().addAll(ButtonType.OK, ButtonType.CANCEL);
        if (dialog.showAndWait().orElse(ButtonType.CANCEL) != ButtonType.OK) return;
        var edge = new PlsSem.Edge(from.getSelectionModel().getSelectedIndex(), to.getSelectionModel().getSelectedIndex());
        if (edge.source() == edge.target() || edges.contains(edge)) throw new IllegalArgumentException("Choose a new connection between different constructs");
        JsonObject proposed=diagramDocument();proposed.getAsJsonArray("edges").add(new Gson().toJsonTree(edge));DiagramClipboard.validate(proposed,columnNames.size());edges.add(edge);invalidate();
    }
    private void removeConstruct(){int[] selectedIndexes=selectedConstructs();if(selectedIndexes.length==0)throw new IllegalArgumentException("Select constructs on the canvas first.");java.util.Set<Integer> removed=new java.util.HashSet<>();for(int index:selectedIndexes)removed.add(index);int[] mapping=new int[constructs.size()];Arrays.fill(mapping,-1);int next=0;for(int index=0;index<mapping.length;index++)if(!removed.contains(index))mapping[index]=next++;List<PlsSem.Edge> retained=edges.stream().filter(edge->mapping[edge.source()]>=0&&mapping[edge.target()]>=0).map(edge->new PlsSem.Edge(mapping[edge.source()],mapping[edge.target()])).toList();rebindLatentSettings(mapping);for(int index=selectedIndexes.length-1;index>=0;index--)constructs.remove(selectedIndexes[index]);edges.clear();edges.addAll(retained);selection.clear();selected=-1;invalidate();}
    private void invalidate() { dirty = true; lastFit = null; lastDiagnostics = null; lastReport = null; lastBootstrap=null; draw(); updateStatus(); resultsTab.setContent(UiAppearance.label("Recalculate after model changes.")); }
    private OrdinalSource ordinalSource(){if(importHistory!=null){if(importHistory.getAsJsonObject("raw").getAsJsonArray("rows").size()>10000)throw new IllegalArgumentException("Ordinal estimation supports at most 10,000 supplied source rows.");var source=ImportHistory.read(importHistory);return new OrdinalSource(source.raw(),source.settings(),source.definitions());}List<List<String>> rows=new ArrayList<>();for(var row:data)rows.add(Arrays.stream(row).mapToObj(Double::toString).toList());return new OrdinalSource(new DataPreparation.Raw(columnNames,rows),new DataPreparation.Settings(',',DataPreparation.Decimal.DOT,"",DataPreparation.Missing.REQUIRE_COMPLETE),columnNames.stream().map(v->new DataPreparation.Column(v,DataPreparation.Kind.NUMERIC)).toList());}
    private void ordinalAnalysis(){if(data.length==0)throw new IllegalArgumentException("Import data first.");var source=ordinalSource();var names=source.definitions().stream().map(DataPreparation.Column::name).toList();List<PlsSem.Block> blocks=new ArrayList<>();for(var block:semBlocks()){int[] mapped=Arrays.stream(block.columns()).map(i->names.indexOf(columnNames.get(i))).toArray();blocks.add(new PlsSem.Block(block.name(),mapped,block.mode(),block.initialWeights(),block.measurementType()));}var selected=OrdinalDialog.show(stage,source.raw(),source.preparation(),source.definitions(),blocks,List.copyOf(edges),ordinalSettings);if(selected.isEmpty())return;ordinalSettings=selected.get();dirty=true;startOrdinal(null);}
