    private void simulationFromModel(){if(data.length==0)throw new IllegalArgumentException("Import data and configure a SEM first.");SemModel.Model model=semSettings!=null&&semSettings.customModel()!=null?semSettings.customModel():SemModel.reflective(columnNames,data,semBlocks(),List.copyOf(edges),semSettings==null||semSettings.correlateExogenous(),true).model();var defaults=SimulationDialog.example();String target=model.parameters().stream().filter(p->p.locations().stream().noneMatch(l->l.kind()==SemModel.Kind.COVARIANCE)).map(SemModel.Parameter::name).findFirst().orElseThrow(()->new IllegalArgumentException("This template has no mean/path target; configure a SEM with free parameters."));simulationDesign=new org.brightstats.stats.SemSimulation.Design(model,null,defaults.sampleSizes(),defaults.repetitions(),List.of(new org.brightstats.stats.SemSimulation.Target(target,0)),defaults.distribution(),7,defaults.missingness(),0,0,1,defaults.uncertainty(),.05,.8,42,1,false,defaults.estimator());simulation();}
