    private void simulationTask(org.brightstats.stats.SemSimulation.Design design,Runnable completion){analysisTask("Simulation attempts completed:",(long)design.sampleSizes().length*design.repetitions(),progress->org.brightstats.stats.SemSimulation.run(design,progress),fit->{showSimulation(fit);if(completion!=null)completion.run();});}
    private void showSimulation(org.brightstats.stats.SemSimulation.Result fit){
        lastFit=null;lastDiagnostics=null;lastBootstrap=null;TabPane tabs=new TabPane();List<String[]> power=new ArrayList<>(),precision=new ArrayList<>();
        for(var row:fit.summaries()){
            power.add(new String[]{Integer.toString(row.sampleSize()),row.parameter(),Integer.toString(row.attempts()),Integer.toString(row.tested()),Integer.toString(row.failures()),format(row.conditionalPower()),format(row.attemptLevelDetectionRate()),format(row.powerMonteCarloSE()),format(row.powerLow95()),format(row.powerHigh95())});
            precision.add(new String[]{Integer.toString(row.sampleSize()),row.parameter(),format(row.populationValue()),format(row.meanEstimate()),format(row.bias()),format(row.rmse()),format(row.empiricalStandardDeviation()),format(row.meanStandardError()),format(row.meanIntervalWidth()),format(row.conditionalCoverage()),format(row.attemptLevelCoverage()),format(row.coverageMonteCarloSE()),format(row.meanInformativeRows()),format(row.meanMissingFraction())});
        }
        resultTab(tabs,"Power and attempt accounting",List.of("N","Parameter","Attempts","Available tests","Unavailable intervals","Conditional power","Detection per attempt","Power MCSE","Power Wilson lower 95%","Power Wilson upper 95%"),power);
        resultTab(tabs,"Bias precision and coverage",List.of("N","Parameter","Population value","Mean estimate","Bias","RMSE","Empirical SD","Mean SE","Mean interval width","Conditional coverage","Coverage per attempt","Coverage MCSE","Mean informative rows","Actual missing fraction"),precision);
        List<String[]> recommendations=new ArrayList<>();for(var row:fit.recommendations())recommendations.add(new String[]{row.parameter(),format(row.desiredPower()),row.firstTestedNPointThreshold()==null?"Not reached":row.firstTestedNPointThreshold().toString(),row.firstTestedNLower95Threshold()==null?"Not reached":row.firstTestedNLower95Threshold().toString()});resultTab(tabs,"Tested sample-size thresholds",List.of("Parameter","Desired power","First tested N: point estimate","First tested N: lower 95% limit"),recommendations);
        List<String[]> failures=new ArrayList<>();fit.issues().forEach((issue,count)->failures.add(new String[]{issue,count.toString()}));resultTab(tabs,"Failure reasons",List.of("Reason","Attempts"),failures);
        if(!fit.replicates().isEmpty()){List<String[]> replicates=new ArrayList<>();for(var trial:fit.replicates())for(var value:trial.targets())replicates.add(new String[]{Integer.toString(trial.sampleSize()),Integer.toString(trial.replicate()),Long.toString(trial.seed()),value.parameter(),format(value.estimate()),format(value.standardError()),java.util.Objects.toString(value.covered(),"Unavailable"),java.util.Objects.toString(value.rejected(),"Unavailable"),trial.issue()});resultTab(tabs,"Retained replicate results",List.of("N","Replicate","Seed","Parameter","Estimate","SE","Covered","Rejected","Issue"),replicates);}
        resultTab(tabs,"Simulation assumptions",List.of("Scope / diagnostic"),fit.warnings().stream().map(v->new String[]{v}).toList());SimulationPlots.add(tabs,fit);Label summary=UiAppearance.label("Model-based power and precision study. Completed attempts: "+fit.completedAttempts()+". Workers: "+fit.effectiveWorkers()+".\nReplicate-result SHA-256: "+fit.replicateResultSha256()+"\n"+String.join("\n",fit.warnings()));summary.setWrapText(true);resultsTab.setContent(new BorderPane(tabs,summary,null,null,null));
        var gson=new GsonBuilder().serializeNulls().serializeSpecialFloatingPointValues().create();JsonObject numeric=new JsonObject();numeric.add("simulation",gson.toJsonTree(fit));JsonObject project=new JsonObject();project.addProperty("format","bright-stats-project");project.addProperty("formatVersion",1);project.addProperty("title","Power and precision study");project.add("columnNames",new JsonArray());project.add("observations",new JsonArray());project.add("blocks",new JsonArray());project.add("edges",new JsonArray());project.add("simulationDesign",gson.toJsonTree(fit.design()));JsonArray tables=new JsonArray();collectReportTables(resultsTab.getContent(),"Simulation",tables);lastReport=ReportArchive.create("SEM_MONTE_CARLO_POWER_PRECISION",project,numeric,tables,fit.warnings());ResultDashboard.install(resultsTab.getContent(),lastReport);workspace.getSelectionModel().select(resultsTab);status.setText("Power study completed; inspect Monte Carlo uncertainty and failed attempts.");
    }
    private void multipleImputation(){if(data.length==0)throw new IllegalArgumentException("Import data first.");var prior=semSettings;var base=prior==null?CovarianceSem.Options.defaults():prior.options();var options=new CovarianceSem.Options(base.maxIterations(),base.gradientTolerance(),base.functionTolerance(),CovarianceSem.Likelihood.NORMAL,true,base.confidence(),CovarianceSem.Information.OBSERVED);var chosen=SemDialog.show(stage,columnNames,data,semBlocks(),List.copyOf(edges),new SemDialog.Settings(options,prior==null||prior.correlateExogenous(),prior==null?null:prior.customModel()));if(chosen.isEmpty())return;if(!chosen.get().options().meanStructure()||chosen.get().options().likelihood()!=CovarianceSem.Likelihood.NORMAL)throw new IllegalArgumentException("Pooled SEM uses explicit Normal mean/covariance models. Enable the mean structure and Normal likelihood.");var analysis=chosen.get().options();var configured=ImputationDialog.show(stage,new org.brightstats.stats.ImputedSem.Options(imputationOptions.imputation(),new org.brightstats.stats.FimlSem.Options(analysis.maxIterations(),analysis.gradientTolerance(),analysis.functionTolerance(),analysis.confidence()),imputationOptions.completeDegreesOfFreedom(),imputationOptions.sandwichCovariance()));if(configured.isEmpty())return;semSettings=chosen.get();imputationOptions=configured.get();dirty=true;startImputedSem(null);}
    private void startImputedSem(Runnable completion){var source=org.brightstats.stats.Matrices.copy(data);var names=List.copyOf(columnNames);var history=importHistory==null?null:importHistory.deepCopy();var blocks=semBlocks();var structure=List.copyOf(edges);var settings=semSettings;var options=imputationOptions;analysisTask("Imputing and analyzing completed datasets ("+(2*options.imputation().imputations())+" stages)...",progress->{SemModel.Model model;int[] columns;if(settings.customModel()!=null){model=settings.customModel();columns=SemDialog.columns(model,names);}else{var prepared=SemModel.reflective(names,source,blocks,structure,settings.correlateExogenous(),true);model=prepared.model();columns=prepared.columns();}var raw=org.brightstats.data.MissingInput.originalAll(history,names,source);double[][] selected=new double[raw.length][columns.length];for(int i=0;i<raw.length;i++)for(int j=0;j<columns.length;j++)selected[i][j]=raw[i][columns[j]];return org.brightstats.stats.ImputedSem.fit(selected,model,options,progress);},fit->{showImputedSem(fit);if(completion!=null)completion.run();});}
    private void showImputedSem(org.brightstats.stats.ImputedSem.Fit fit){lastFit=null;lastDiagnostics=null;lastBootstrap=null;TabPane tabs=new TabPane();List<String[]> rows=new ArrayList<>();for(var term:fit.pooled().terms())rows.add(new String[]{term.parameter(),format(term.estimate()),format(term.standardError()),format(term.degreesOfFreedom()),format(term.fractionMissingInformation()),format(term.statistic()),UiAppearance.probability(term.pValue()),format(term.lower()),format(term.upper())});resultTab(tabs,"Pooled SEM parameters",List.of("Parameter","Estimate","Pooled SE","Pooling df","Fraction missing information","Ratio","P","Pointwise lower","Pointwise upper"),rows);resultTab(tabs,"Imputation diagnostics",List.of("Quantity","Value"),List.of(new String[]{"Supplied source rows",Integer.toString(fit.suppliedRows())},new String[]{"Informative source rows",Integer.toString(fit.sourceRows().size())},new String[]{"Missing cells",Integer.toString(fit.missingCells())},new String[]{"Imputations",Integer.toString(fit.pooled().imputations())},new String[]{"Mean-trace split R-hat screen",format(fit.maximumSplitRhat())},new String[]{"Within-analysis covariance",fit.options().sandwichCovariance()?"Case-score sandwich":"Observed information"}));List<String[]> analyses=new ArrayList<>();for(var member:fit.analyses())analyses.add(new String[]{Integer.toString(member.index()),member.dataSha256(),Boolean.toString(member.converged()),Boolean.toString(member.locallyIdentified()),Integer.toString(member.iterations())});resultTab(tabs,"Completed-analysis provenance",List.of("Imputation","Completed-data SHA-256","Converged","Locally identified","Iterations"),analyses);semMatrix(tabs,"Within-imputation covariance",fit.pooled().withinCovariance(),fit.pooled().labels());semMatrix(tabs,"Between-imputation covariance",fit.pooled().betweenCovariance(),fit.pooled().labels());semMatrix(tabs,"Total pooled covariance",fit.pooled().totalCovariance(),fit.pooled().labels());resultTab(tabs,"Imputation assumptions",List.of("Scope / diagnostic"),fit.warnings().stream().map(v->new String[]{v}).toList());ImputationPlots.add(tabs,fit);Label summary=UiAppearance.label("Continuous multiple imputation, complete-data SEM and Rubin pooling. No pooled likelihood or fit index is fabricated.\n"+String.join("\n",fit.warnings()));summary.setWrapText(true);resultsTab.setContent(new BorderPane(tabs,summary,null,null,null));JsonObject numeric=new JsonObject();numeric.add("imputedSem",new GsonBuilder().serializeNulls().serializeSpecialFloatingPointValues().create().toJsonTree(fit));lastReport=report("MULTIPLE_IMPUTATION_SEM_RUBIN",numeric,fit.warnings());workspace.getSelectionModel().select(resultsTab);status.setText("Multiple-imputation SEM completed; inspect chains, assumptions and pooled uncertainty.");}
    private void fiml(){if(data.length==0)throw new IllegalArgumentException("Import data first.");var prior=semSettings;var base=prior==null?CovarianceSem.Options.defaults():prior.options();var options=new CovarianceSem.Options(base.maxIterations(),base.gradientTolerance(),base.functionTolerance(),CovarianceSem.Likelihood.NORMAL,true,base.confidence(),CovarianceSem.Information.OBSERVED);var chosen=SemDialog.show(stage,columnNames,data,semBlocks(),List.copyOf(edges),new SemDialog.Settings(options,prior==null||prior.correlateExogenous(),prior==null?null:prior.customModel()));if(chosen.isEmpty())return;if(!chosen.get().options().meanStructure()||chosen.get().options().likelihood()!=CovarianceSem.Likelihood.NORMAL)throw new IllegalArgumentException("FIML uses a raw observed-data Normal likelihood and an explicit mean structure. Enable both settings.");semSettings=chosen.get();dirty=true;startFiml(null);}
    private void startFiml(Runnable completion){var source=org.brightstats.stats.Matrices.copy(data);var names=List.copyOf(columnNames);var history=importHistory==null?null:importHistory.deepCopy();var blocks=semBlocks();var structure=List.copyOf(edges);var settings=semSettings;analysisTask("Fitting original observed-data missingness patterns...",()->{SemModel.Model model;int[] columns;if(settings.customModel()!=null){model=settings.customModel();columns=SemDialog.columns(model,names);}else{var prepared=SemModel.reflective(names,source,blocks,structure,settings.correlateExogenous(),true);model=prepared.model();columns=prepared.columns();}var raw=org.brightstats.data.MissingInput.originalAll(history,names,source);double[][] selected=new double[raw.length][columns.length];for(int i=0;i<raw.length;i++)for(int j=0;j<columns.length;j++)selected[i][j]=raw[i][columns[j]];var option=settings.options();return org.brightstats.stats.FimlSem.fit(selected,model,new org.brightstats.stats.FimlSem.Options(option.maxIterations(),option.gradientTolerance(),option.functionTolerance(),option.confidence()));},fit->{showFiml(fit);if(completion!=null)completion.run();});}
    private void showFiml(org.brightstats.stats.FimlSem.Fit fit){lastFit=null;lastDiagnostics=null;lastBootstrap=null;TabPane tabs=new TabPane();List<String[]> terms=new ArrayList<>();for(var term:fit.terms())terms.add(new String[]{term.parameter(),format(term.estimate()),format(term.standardError()),format(term.sandwichStandardError()),format(term.z()),UiAppearance.probability(term.pValue()),format(term.lower()),format(term.upper())});resultTab(tabs,"FIML parameters",List.of("Parameter","Estimate","Observed-information SE","Case-score sandwich SE","Model z","Model P","Pointwise lower","Pointwise upper"),terms);resultTab(tabs,"FIML summary",List.of("Quantity","Value"),List.of(new String[]{"Supplied original rows",Integer.toString(fit.suppliedRows())},new String[]{"Informative rows",Integer.toString(fit.observations())},new String[]{"Fully unobserved rows",Integer.toString(fit.emptyRows())},new String[]{"Observed patterns",Integer.toString(fit.observedPatterns())},new String[]{"Converged",Boolean.toString(fit.converged())},new String[]{"Locally identified",Boolean.toString(fit.locallyIdentified())},new String[]{"Log likelihood",format(fit.logLikelihood())},new String[]{"AIC",format(fit.aic())},new String[]{"BIC",format(fit.bic())}));List<String> observed=Arrays.stream(fit.model().observed()).mapToObj(fit.model().variables()::get).toList();List<String[]> patterns=new ArrayList<>();for(var pattern:fit.missingPatterns())patterns.add(new String[]{Arrays.stream(pattern.columns()).mapToObj(observed::get).collect(java.util.stream.Collectors.joining(", ")),Integer.toString(pattern.rows())});resultTab(tabs,"Observed missingness patterns",List.of("Observed variables","Original rows"),patterns);semMatrix(tabs,"FIML implied covariance",fit.impliedCovariance(),observed);resultTab(tabs,"FIML assumptions",List.of("Scope / diagnostic"),fit.warnings().stream().map(v->new String[]{v}).toList());Label summary=UiAppearance.label("Continuous observed-data Gaussian FIML: original missingness and removed source rows are recovered; no mean replacement is used in this likelihood.\n"+String.join("\n",fit.warnings()));summary.setWrapText(true);resultsTab.setContent(new BorderPane(tabs,summary,null,null,null));JsonObject numeric=new JsonObject();numeric.add("fiml",new GsonBuilder().serializeSpecialFloatingPointValues().create().toJsonTree(fit));lastReport=report("SEM_FIML_OBSERVED_NORMAL",numeric,fit.warnings());workspace.getSelectionModel().select(resultsTab);status.setText("FIML completed; review missingness assumptions, convergence and information.");}
    private void readiness(){if(activeTask!=null)throw new IllegalArgumentException("Finish or cancel the running analysis first.");var source=org.brightstats.stats.Matrices.copy(data);var names=List.copyOf(columnNames);var blocks=semBlocks();var structure=List.copyOf(edges);var history=importHistory==null?null:importHistory.deepCopy();analysisTask("Reviewing data and model readiness...",()->org.brightstats.data.AnalysisReadiness.inspect(names,source,blocks,structure,history),review->{Dialog<Void> dialog=new Dialog<>();dialog.initOwner(stage);dialog.setTitle("Analysis readiness");dialog.getDialogPane().getButtonTypes().add(ButtonType.CLOSE);List<String[]> rows=review.findings().stream().map(v->new String[]{v.severity().name(),v.area(),v.detail()}).toList();dialog.getDialogPane().setContent(TableTools.wrap(table(List.of("Status","Area","What to review"),rows)));dialog.getDialogPane().setPrefSize(950,520);dialog.setResizable(true);dialog.show();});}
