    private void calculate() {
        if (data.length == 0 || constructs.isEmpty()) throw new IllegalArgumentException("Import data and add constructs first");
        int[] used = constructs.stream().flatMapToInt(c -> Arrays.stream(c.columns)).distinct().toArray();
        var warnings = selectedWarnings(used);
        if (!warnings.isEmpty() && smokeOutput == null
                && new Alert(Alert.AlertType.WARNING, String.join("\n", warnings) + "\nContinue with this model?", ButtonType.YES, ButtonType.NO)
                        .showAndWait().orElse(ButtonType.NO) != ButtonType.YES) return;
        lastReport = null; lastBootstrap = null;
        var blocks = constructs.stream().map(c -> new PlsSem.Block(c.name, c.columns, c.mode, c.initialWeights, c.measurementType)).toList();
        List<PlsSem.Edge> structure = List.copyOf(edges); double[][] observations = data;
        sidebar.setDisable(true); status.setText("Calculating PLS-SEM...");
        PlsSem.Options options = calculationOptions;
        Task<Calculation> task = new Task<>() {
            @Override protected Calculation call() {
                var model = PlsSem.fit(observations, blocks, structure, options);
                return new Calculation(model, model.converged() ? ModelDiagnostics.compute(observations, blocks, structure, model) : null);
            }
        };
        beginTask(task);
        task.setOnSucceeded(event -> {
            endTask(); lastFit = task.getValue().model(); lastDiagnostics = task.getValue().diagnostics(); showPlsResults(); draw();
            status.setText(lastFit.converged() ? "PLS-SEM converged in " + lastFit.iterations() + " iterations." : "Iteration limit reached; inspect results with care.");
            if (smokeOutput != null) {
                workspace.getSelectionModel().select(modelTab);
                PauseTransition pause = new PauseTransition(Duration.millis(350)); pause.setOnFinished(done -> snapshotAndExit()); pause.play();
            } else workspace.getSelectionModel().select(resultsTab);
        });
        task.setOnFailed(event -> { endTask(); fail(task.getException()); });
        dispatchCalculation(task);
    }
    /** Smoke cancellation checks deliberately cancel queued work before dispatch. Engine checks separately exercise interruption. */
    private void dispatchCalculation(Task<?> task){if(smokeOutput!=null)Platform.runLater(()->{if(!task.isCancelled())Thread.ofVirtual().start(task);});else Thread.ofVirtual().start(task);}
    private void beginTask(Task<?> task) {
        if(modelMotion!=null)modelMotion.finish();calculationProgress.begin(task,status.getText(),-1);task.workDoneProperty().addListener((o,a,b)->{if(activeTask==task&&b.doubleValue()>=0){calculationProgress.expected((long)task.getTotalWork());calculationProgress.report(b.longValue());}});activeTask=task;if(homeTab.getContent()!=null)homeTab.getContent().setDisable(true); diagram.setDisable(true); sidebar.setDisable(true); cancelCalculation.setDisable(false);taskActivity.getProperties().put("brightstats.activeActivity",true);taskActivity.setVisible(UiAppearance.effectiveMotion()==org.brightstats.data.UserPreferences.Motion.FULL);elapsedTask.setVisible(true);elapsedTask.setText("0 s elapsed");taskStarted=System.nanoTime();taskClock=new javafx.animation.Timeline(new javafx.animation.KeyFrame(Duration.seconds(1),e->elapsedTask.setText(((System.nanoTime()-taskStarted)/1_000_000_000L)+" s elapsed")));taskClock.setCycleCount(javafx.animation.Animation.INDEFINITE);taskClock.play();
        task.setOnCancelled(event -> { endTask(); lastReport=null; resultsTab.setContent(UiAppearance.label("Calculation cancelled; no partial result was saved.")); status.setText("Calculation cancelled."); });
    }
    private void endTask() { long generation=calculationProgress.generation;Platform.runLater(()->calculationProgress.rendered(generation));activeTask=null;if(homeTab.getContent()!=null)homeTab.getContent().setDisable(false); diagram.setDisable(false); sidebar.setDisable(false); cancelCalculation.setDisable(true);taskActivity.getProperties().put("brightstats.activeActivity",false);taskActivity.setVisible(false);elapsedTask.setVisible(false);if(taskClock!=null)taskClock.stop(); }
    private <T> void analysisTask(String caption,java.util.function.Supplier<T> work,java.util.function.Consumer<T> success) {
        analysisTask(caption,progress->work.get(),success);
    }
    private <T> void analysisTask(String caption,java.util.function.Function<java.util.function.IntConsumer,T> work,java.util.function.Consumer<T> success) {
        analysisTask(caption,-1,work,success);
    }
    private <T> void analysisTask(String caption,long total,java.util.function.Function<java.util.function.IntConsumer,T> work,java.util.function.Consumer<T> success) {
        java.util.concurrent.atomic.AtomicLong reported=new java.util.concurrent.atomic.AtomicLong(-1);lastReport=null;status.setText(caption);Task<T> task=new Task<>(){@Override protected T call(){return work.apply(step->{reported.set(step);updateMessage(caption+" "+step);});}};beginTask(task);calculationProgress.expected(total);
        task.messageProperty().addListener((observable,previous,message)->{if(activeTask==task){status.setText(message);calculationProgress.report(reported.get());}});
        task.setOnSucceeded(event->{endTask();try{success.accept(task.getValue());workspace.getSelectionModel().select(resultsTab);}catch(Throwable error){fail(error);}});task.setOnFailed(event->{endTask();fail(task.getException());});dispatchCalculation(task);
    }
