    private void jointSem(boolean sequence){
        if(data.length==0)throw new IllegalArgumentException("Import data first.");var chosen=GroupDialog.showMembership(stage,data.length,groupingColumns(),semMembership);if(chosen.isEmpty())return;SemInvariance.Stage level=semGroupStage;boolean strict=semStrictSequence;if(sequence){var choice=new ChoiceDialog<>(strict?"Strict sequence (five models)":"Basic sequence (four models)",List.of("Basic sequence (four models)","Strict sequence (five models)"));choice.initOwner(stage);choice.setTitle("Measurement invariance sequence");choice.setHeaderText("Mean structure is required; the first selected group is the latent-mean reference.");var result=choice.showAndWait();if(result.isEmpty())return;strict=result.get().startsWith("Strict");}else{var choice=new ChoiceDialog<>(level,SemInvariance.Stage.values());choice.initOwner(stage);choice.setTitle("Joint SEM constraints");choice.setHeaderText("Configural fits separate group parameters; other levels impose measurement equalities.");var result=choice.showAndWait();if(result.isEmpty())return;level=result.get();}
        var previous=semSettings;if(sequence||level!=SemInvariance.Stage.CONFIGURAL&&level!=SemInvariance.Stage.METRIC){var options=previous==null?CovarianceSem.Options.defaults():previous.options();previous=new SemDialog.Settings(new CovarianceSem.Options(options.maxIterations(),options.gradientTolerance(),options.functionTolerance(),options.likelihood(),true,options.confidence(),options.information()),previous==null||previous.correlateExogenous(),previous==null?null:previous.customModel());}var selected=SemDialog.show(stage,columnNames,data,semBlocks(),List.copyOf(edges),previous);if(selected.isEmpty())return;if(sequence&&!selected.get().options().meanStructure())throw new IllegalArgumentException("Enable the mean structure for the invariance sequence.");semMembership=chosen.get();semGroupStage=level;semStrictSequence=strict;semSettings=selected.get();dirty=true;startJointSem(sequence,null);
    }
    private void startJointSem(boolean sequence,Runnable completion){
        var membership=semMembership;membership.validate(data.length);var settings=semSettings;var level=semGroupStage;boolean strict=semStrictSequence;double[][] source=org.brightstats.stats.Matrices.copy(data);var names=List.copyOf(columnNames);var blocks=semBlocks();var structure=List.copyOf(edges);analysisTask(sequence?"Fitting measurement invariance sequence...":"Estimating joint group SEM likelihood...",progress->{double[][] a=selectedRows(source,membership.selection().rowsA()),b=selectedRows(source,membership.selection().rowsB()),pooled=new double[a.length+b.length][];System.arraycopy(a,0,pooled,0,a.length);System.arraycopy(b,0,pooled,a.length,b.length);SemModel.Prepared template;if(settings.customModel()!=null){var model=settings.customModel();int[] columns=SemDialog.columns(model,names);boolean[] observed=new boolean[model.variables().size()];for(int index:model.observed())observed[index]=true;int[] factors=java.util.stream.IntStream.range(0,observed.length).filter(i->!observed[i]).toArray();template=new SemModel.Prepared(model,columns,factors);}else template=SemModel.reflective(names,pooled,blocks,structure,settings.correlateExogenous(),settings.options().meanStructure());var samples=List.of(SemInvariance.Sample.fromData(membership.selection().nameA(),template.select(a),settings.options()),SemInvariance.Sample.fromData(membership.selection().nameB(),template.select(b),settings.options()));if(sequence)return new JointSemCalculation(null,SemInvariance.sequence(template,samples,settings.options(),strict,progress));if(level==SemInvariance.Stage.CONFIGURAL){var groups=samples.stream().map(sample->new MultiGroupSem.Group(sample.name(),sample.observations(),sample.covariance(),sample.means(),template.model(),java.util.Map.of())).toList();return new JointSemCalculation(MultiGroupSem.fit(groups,settings.options()),null);}return new JointSemCalculation(SemInvariance.fitStage(template,samples,level,settings.options()),null);},result->{lastFit=null;lastDiagnostics=null;lastBootstrap=null;if(result.sequence()!=null)showSemInvariance(result.sequence());else showJointSem(result.point());status.setText(sequence?"Measurement invariance sequence completed; inspect each stage's status.":"Joint group SEM "+(result.point().converged()?"converged.":"is provisional."));if(completion!=null)completion.run();});
    }
