    private void showSemInvariance(SemInvariance.Result result){
        TabPane tabs=new TabPane();List<String[]> fits=new ArrayList<>(),comparisons=new ArrayList<>(),parameters=new ArrayList<>(),contributions=new ArrayList<>(),means=new ArrayList<>(),notes=new ArrayList<>();JsonArray numericMeans=new JsonArray();var gson=new GsonBuilder().serializeSpecialFloatingPointValues().create();for(var step:result.steps()){String label=step.stage().toString();var fit=step.fit();if(fit==null){fits.add(new String[]{label,step.stage().referenceCode(),"Unavailable","","","","","","","","","","",""});notes.add(new String[]{label,step.failure()});continue;}fits.add(new String[]{label,step.stage().referenceCode(),format(fit.chiSquare()),Integer.toString(fit.degreesOfFreedom()),probability(fit.chiSquarePValue()),format(fit.cfi()),format(fit.tli()),format(fit.rmsea()),format(fit.srmr()),format(fit.aic()),format(fit.bic()),Boolean.toString(fit.converged()),Boolean.toString(fit.identified()),Boolean.toString(fit.proper())});parameters.addAll(jointParameterRows(fit,label));contributions.addAll(jointContributionRows(fit,label));var contrasts=MultiGroupSem.meanContrasts(fit,fit.groups().get(0).input().name());means.addAll(jointMeanRows(contrasts,label));JsonObject savedMeans=new JsonObject();savedMeans.addProperty("stage",step.stage().name());savedMeans.add("contrasts",gson.toJsonTree(contrasts));numericMeans.add(savedMeans);for(String warning:fit.warnings())notes.add(new String[]{label,warning});if(step.comparisonUnavailable()!=null)notes.add(new String[]{label,step.comparisonUnavailable()});if(step.previousComparison()!=null){var comparison=step.previousComparison();comparisons.add(new String[]{label,format(comparison.difference()),Integer.toString(comparison.differenceDf()),probability(comparison.pValue()),format(comparison.deltaCfi()),format(comparison.deltaRmsea()),comparison.nestingProof()});}}
        resultTab(tabs,"Invariance sequence",List.of("Model","Reference code","Chi-square","df","P","CFI","TLI","RMSEA","SRMR","Gaussian AIC","Gaussian BIC","Converged","Identified","Proper"),fits);resultTab(tabs,"Nested stage comparisons",List.of("Restricted model","Delta chi-square","Delta df","P","Delta CFI (R − U)","Delta RMSEA (R − U)","Nesting justification"),comparisons);resultTab(tabs,"Stage global parameters",List.of("Model","Parameter","Estimate","SE","z","P","Lower","Upper","Group bindings"),parameters);resultTab(tabs,"Stage mean contrasts",List.of("Model","Reference","Compared","Variable","Reference mean","Compared mean","Difference","SE","z","P","Lower","Upper","Zero first-order variance"),means);resultTab(tabs,"Stage group contributions",List.of("Model","Group","N","Discrepancy","Chi-square contribution","SRMR","Gaussian LL","Proper"),contributions);resultTab(tabs,"Stage diagnostics",List.of("Model","Note"),notes);Label summary=new Label("CB-SEM "+(result.strict()?"strict":"basic")+" measurement invariance · first group supplies the latent-mean reference.\n"+String.join("\n",result.warnings()));summary.setWrapText(true);summary.setPadding(new Insets(8));resultsTab.setContent(new BorderPane(tabs,summary,null,null,null));JsonObject numeric=new JsonObject();numeric.add("semInvariance",gson.toJsonTree(result));numeric.add("invarianceMeanContrasts",numericMeans);lastReport=report("CB-SEM measurement invariance",numeric,result.warnings());
    }
    private void compareJointSemReports(){FileChooser chooser=new FileChooser();chooser.setTitle("Choose restricted joint SEM report");chooser.getExtensionFilters().add(new FileChooser.ExtensionFilter("Bright-Stats report","*.bsreport.json"));var restricted=chooser.showOpenDialog(stage);if(restricted==null)return;chooser.setTitle("Choose unrestricted joint SEM report");var unrestricted=chooser.showOpenDialog(stage);if(unrestricted==null)return;try{showJointSemComparison(ReportArchive.read(restricted.toPath()),ReportArchive.read(unrestricted.toPath()));}catch(Exception problem){fail(problem);}}
    private void showJointSemComparison(JsonObject restricted,JsonObject unrestricted){var comparison=MultiGroupSemComparison.compare(MultiGroupSemReports.fit(restricted),MultiGroupSemReports.fit(unrestricted));TabPane tabs=new TabPane();List<String[]> rows=new ArrayList<>();double[] values={comparison.restrictedChiSquare(),comparison.unrestrictedChiSquare(),comparison.restrictedDf(),comparison.unrestrictedDf(),comparison.difference(),comparison.differenceDf(),comparison.pValue(),comparison.deltaCfi(),comparison.deltaRmsea(),comparison.restrictedAic(),comparison.unrestrictedAic(),comparison.restrictedBic(),comparison.unrestrictedBic()};String[] labels={"Restricted chi-square","Unrestricted chi-square","Restricted df","Unrestricted df","Delta chi-square","Delta df","P","Delta CFI (R − U)","Delta RMSEA (R − U)","Restricted Gaussian AIC","Unrestricted Gaussian AIC","Restricted Gaussian BIC","Unrestricted Gaussian BIC"};for(int i=0;i<values.length;i++)rows.add(new String[]{labels[i],format(values[i])});resultTab(tabs,"Joint likelihood-ratio comparison",List.of("Measure","Value"),rows);Label summary=new Label(comparison.nestingProof());summary.setWrapText(true);summary.setPadding(new Insets(8));resultsTab.setContent(new BorderPane(tabs,summary,null,null,null));var gson=new GsonBuilder().serializeSpecialFloatingPointValues().create();JsonObject numeric=new JsonObject();numeric.add("jointSemComparison",gson.toJsonTree(comparison));numeric.add("restricted",restricted.getAsJsonObject("results").get("multiGroupSem").deepCopy());numeric.add("unrestricted",unrestricted.getAsJsonObject("results").get("multiGroupSem").deepCopy());lastReport=report("Joint SEM comparison",numeric,List.of());JsonObject projects=new JsonObject();projects.addProperty("format","joint-sem-comparison-inputs");projects.add("restrictedProject",restricted.get("project").deepCopy());projects.add("unrestrictedProject",unrestricted.get("project").deepCopy());lastReport.add("project",projects);workspace.getSelectionModel().select(resultsTab);}
    private java.util.Map<String,List<String>> groupingColumns(){return org.brightstats.data.GroupMembership.columns(importHistory);}
    private void groups(boolean permutation){if(data.length==0)throw new IllegalArgumentException("Import data first.");var choice=GroupDialog.show(stage,data.length,groupingColumns(),groupSettings,permutation);if(choice.isEmpty())return;groupSettings=choice.get();dirty=true;startGroups(permutation,null);}
    private void startGroups(boolean permutation,Runnable completion){
        var settings=groupSettings;settings.validate(data.length);var blocks=semBlocks();var structure=List.copyOf(edges);var options=calculationOptions;double[][] observations=org.brightstats.stats.Matrices.copy(data);analysisTask(permutation?"Permuting group membership and assessing invariance...":"Bootstrapping group models...",progress->permutation?new GroupCalculation(PlsPermutation.fit(observations,blocks,structure,options,settings.selection(),settings.consistent(),settings.permutation(),progress),null):new GroupCalculation(null,PlsGroupBootstrap.fit(observations,blocks,structure,options,settings.selection(),settings.consistent(),settings.bootstrap(),settings.retained(),progress)),result->{lastFit=null;lastDiagnostics=null;lastBootstrap=null;if(result.permutation()!=null)showGroupPermutation(result.permutation());else showGroupBootstrap(result.bootstrap());status.setText("Group analysis completed: "+(result.permutation()!=null?result.permutation().successful():result.bootstrap().successful())+" usable resamples.");if(completion!=null)completion.run();});
    }
    private List<String> groupWarnings(PlsGroups.Point point,List<String> source){List<String> warnings=new ArrayList<>(source);warnings.addAll(point.groupA().diagnostics().warnings().stream().map(v->point.groupA().name()+": "+v).toList());warnings.addAll(point.groupB().diagnostics().warnings().stream().map(v->point.groupB().name()+": "+v).toList());return warnings;}
    private void groupPointTabs(TabPane tabs,PlsGroups.Point point){
        resultTab(tabs,"Group membership",List.of("Group","Observations","Prepared rows"),List.of(new String[]{point.groupA().name(),Integer.toString(point.groupA().rows().length),GroupDialog.formatRows(point.groupA().rows())},new String[]{point.groupB().name(),Integer.toString(point.groupB().rows().length),GroupDialog.formatRows(point.groupB().rows())}));List<String[]> rows=new ArrayList<>();for(var group:List.of(point.groupA(),point.groupB())){var reliability=group.diagnostics().reliability();double[] r2=group.model().rSquared();for(int j=0;j<constructs.size();j++)rows.add(new String[]{group.name(),constructs.get(j).name,format(reliability[j].alpha()),format(reliability[j].rhoA()),format(reliability[j].rhoC()),format(reliability[j].ave()),format(r2[j]),Integer.toString(group.model().iterations())});}resultTab(tabs,"Group diagnostics",List.of("Group","Construct","Alpha","rho_A","rho_C","AVE","R-square","Iterations"),rows);
    }
    private void groupReport(TabPane tabs,PlsGroups.Point point,JsonObject numeric,List<String> warnings,String caption){Label summary=new Label(caption+"\nMembership: "+groupSettings.membershipSource()+"\n"+String.join("\n",warnings));summary.setWrapText(true);summary.setPadding(new Insets(8));resultsTab.setContent(new BorderPane(tabs,summary,null,null,null));lastReport=report(point.consistent()?"PLSc multigroup":"PLS multigroup",numeric,warnings);}
    private static void histogramRows(List<String[]> rows,String group,String family,String parameter,EmpiricalHistogram histogram){double[] breaks=histogram.breaks();int[] counts=histogram.counts();for(int i=0;i<counts.length;i++)rows.add(new String[]{group,family,parameter,format(breaks[i]),format(breaks[i+1]),Integer.toString(counts[i])});}
    private void showGroupPermutation(PlsPermutation.Result result){
        TabPane tabs=new TabPane();List<String[]> contrasts=new ArrayList<>(),histograms=new ArrayList<>();for(var test:result.tests()){contrasts.add(new String[]{test.parameter().family(),test.parameter().label(),format(test.groupA()),format(test.groupB()),format(test.difference()),format(test.permutationMean()),format(test.permutationSd()),format(test.lower()),format(test.upper()),probability(test.pValue()),Boolean.toString(test.referenceZeroDifference())});histogramRows(histograms,"Difference",test.parameter().family(),test.parameter().label(),test.histogram());}resultTab(tabs,"Group permutation",List.of("Family","Parameter","Group A","Group B","A − B","Null mean","Null SD","Lower","Upper","P","Reference zero edge"),contrasts);
        if(!result.micom().isEmpty()){List<String[]> composition=new ArrayList<>(),moments=new ArrayList<>();for(var test:result.micom()){composition.add(new String[]{test.construct(),format(test.originalCorrelation()),format(test.permutationMeanCorrelation()),format(test.correlationLower()),probability(test.compositionP()),Boolean.toString(test.compositional()),test.verdict(),Boolean.toString(test.referenceZeroCorrelationDistance())});moments.add(new String[]{test.construct(),format(test.meanDifference()),format(test.meanPermutationMean()),format(test.meanLower()),format(test.meanUpper()),probability(test.meanP()),format(test.logVarianceRatio()),format(test.logVariancePermutationMean()),format(test.logVarianceLower()),format(test.logVarianceUpper()),probability(test.varianceP()),Boolean.toString(test.equalMeans()),Boolean.toString(test.equalVariances())});}resultTab(tabs,"MICOM composition",List.of("Construct","Original c","Null mean c","Lower critical c","P","Composition supported","Overall verdict","Reference zero edge"),composition);resultTab(tabs,"MICOM means / variance",List.of("Construct","Mean A − B","Null mean","Mean lower","Mean upper","Mean P","Log variance A/B","Null log variance","Variance lower","Variance upper","Variance P","Equal means","Equal variances"),moments);}
        groupPointTabs(tabs,result.point());resultTab(tabs,"Permutation histograms",List.of("Statistic","Family","Parameter","Bin lower","Bin upper","Count"),histograms);JsonObject numeric=new JsonObject();numeric.add("groupPermutation",new GsonBuilder().serializeSpecialFloatingPointValues().create().toJsonTree(result));groupReport(tabs,result.point(),numeric,groupWarnings(result.point(),result.warnings()),"Group-label permutation · "+result.successful()+" successful; "+result.failed()+" failed · "+result.options().convention()+"\nMICOM mean/variance tests use fixed pooled scores. Configural review: "+result.options().configuralConfirmed());
    }
    private void showGroupBootstrap(PlsGroupBootstrap.Result result){
        TabPane tabs=new TabPane();List<String[]> tests=new ArrayList<>(),intervals=new ArrayList<>(),corrected=new ArrayList<>(),histograms=new ArrayList<>();for(var comparison:result.comparisons()){var term=comparison.parameter();tests.add(new String[]{term.family(),term.label(),format(comparison.difference()),format(comparison.parametric().statistic()),format(comparison.parametric().degreesOfFreedom()),probability(comparison.parametric().pValue()),format(comparison.welch().statistic()),format(comparison.welch().degreesOfFreedom()),probability(comparison.welch().pValue()),probability(comparison.mgaDirectionalP()),probability(comparison.mgaTestP()),!comparison.correctedIntervalsAvailable()?"Unavailable":comparison.correctedIntervalsOverlap()?"Overlap":"Do not overlap"});for(int side=0;side<2;side++){var estimate=side==0?comparison.groupA():comparison.groupB();String group=side==0?result.point().groupA().name():result.point().groupB().name();intervals.add(new String[]{group,term.family(),term.label(),format(estimate.original()),format(estimate.mean()),format(estimate.standardError()),format(estimate.lower()),format(estimate.upper()),String.join("; ",estimate.interval().warnings())});corrected.add(new String[]{group,term.family(),term.label(),format(estimate.correctedInterval().lower()),format(estimate.correctedInterval().upper()),String.join("; ",estimate.correctedInterval().warnings())});histogramRows(histograms,group,term.family(),term.label(),side==0?comparison.groupAHistogram():comparison.groupBHistogram());}}
        resultTab(tabs,"MGA comparisons",List.of("Family","Parameter","A − B","Parametric |t|","Parametric df","Parametric P","Welch |t|","Welch df","Welch P","PLS-MGA directional P","PLS-MGA test P","Corrected group intervals"),tests);resultTab(tabs,"Group confidence intervals",List.of("Group","Family","Parameter","Original","Mean","Bootstrap SE","Lower","Upper","Notes"),intervals);resultTab(tabs,"Corrected group intervals",List.of("Group","Family","Parameter","Lower","Upper","Notes"),corrected);groupPointTabs(tabs,result.point());resultTab(tabs,"Bootstrap histograms",List.of("Group","Family","Parameter","Bin lower","Bin upper","Count"),histograms);JsonObject numeric=new JsonObject();numeric.add("groupBootstrap",new GsonBuilder().serializeSpecialFloatingPointValues().create().toJsonTree(result));groupReport(tabs,result.point(),numeric,groupWarnings(result.point(),result.warnings()),"Within-group case bootstrap · "+result.successful()+" successful pairs; "+result.failed()+" failed · "+result.options().convention()+" · confidence "+result.options().confidence()+"\nGroup interval non-overlap is conservative; it is not a confidence interval for A − B.");
    }
