    private void showSegmentation(PredictionSegmentation.Result result){TabPane tabs=new TabPane();List<String[]> summary=new ArrayList<>(),groups=new ArrayList<>(),paths=new ArrayList<>(),measurement=new ArrayList<>(),assignments=new ArrayList<>(),trace=new ArrayList<>(),starts=new ArrayList<>(),diagnostics=new ArrayList<>();summary.add(new String[]{"Pooled objective",format(result.pooledObjective())});summary.add(new String[]{"Segment objective",format(result.objective())});summary.add(new String[]{"Selected start",Integer.toString(result.bestStart()+1)});summary.add(new String[]{"Search exhausted",Boolean.toString(result.converged())});summary.add(new String[]{"Rejected candidates across starts",Integer.toString(result.rejectedCandidates())});for(var segment:result.segments()){double[] r2=segment.fit().rSquared();for(int construct=0;construct<result.blocks().size();construct++)if(Double.isFinite(r2[construct]))groups.add(new String[]{Integer.toString(segment.index()+1),Integer.toString(segment.rows().length),format((double)segment.rows().length/result.observations()),result.blocks().get(construct).name(),format(r2[construct]),Integer.toString(segment.fit().iterations())});double[][] coefficients=segment.fit().pathCoefficients(),weights=segment.fit().weights(),loadings=segment.fit().loadings();for(var edge:result.edges())paths.add(new String[]{Integer.toString(segment.index()+1),result.blocks().get(edge.source()).name(),result.blocks().get(edge.target()).name(),format(coefficients[edge.source()][edge.target()]),format(coefficients[edge.source()][edge.target()]-result.pooled().pathCoefficients()[edge.source()][edge.target()])});for(int construct=0;construct<result.blocks().size();construct++){int[] columns=result.blocks().get(construct).columns();for(int index=0;index<columns.length;index++)measurement.add(new String[]{Integer.toString(segment.index()+1),result.blocks().get(construct).name(),columnNames.get(columns[index]),format(weights[construct][index]),format(loadings[construct][index])});}}int[] initial=result.initialAssignments(),labels=result.assignments();double[][] distances=result.distances();List<String> columns=new ArrayList<>(List.of("Prepared row","Initial group","Final group"));for(int group=0;group<result.options().segments();group++)columns.add("Distance "+(group+1));for(int row=0;row<result.observations();row++){String[] values=new String[3+result.options().segments()];values[0]=Integer.toString(row+1);values[1]=Integer.toString(initial[row]+1);values[2]=Integer.toString(labels[row]+1);for(int group=0;group<result.options().segments();group++)values[group+3]=format(distances[row][group]);assignments.add(values);}for(var step:result.trace())trace.add(new String[]{Integer.toString(step.iteration()),step.phase(),format(step.objective()),Integer.toString(step.considered()),step.acceptedRow()<0?"":Integer.toString(step.acceptedRow()+1),step.source()<0?"":Integer.toString(step.source()+1),step.target()<0?"":Integer.toString(step.target()+1),format(step.improvement())});for(var start:result.starts())starts.add(new String[]{Integer.toString(start.index()+1),Long.toString(start.seed()),Boolean.toString(start.converged()),format(start.objective()),Integer.toString(start.iterations()),Integer.toString(start.groupFits()),start.failure()==null?"":start.failure()});for(var warning:result.warnings())diagnostics.add(new String[]{"Assumption / diagnostic",warning});resultTab(tabs,"Segmentation summary",List.of("Metric","Value"),summary);resultTab(tabs,"Group fit",List.of("Group","Size","Proportion","Response","R²","PLS iterations"),groups);resultTab(tabs,"Group paths",List.of("Group","Source","Target","Coefficient","Difference from pooled"),paths);resultTab(tabs,"Group measurement",List.of("Group","Construct","Indicator","Weight","Loading"),measurement);resultTab(tabs,"Assignments and distances",columns,assignments);resultTab(tabs,"Search trace",List.of("Iteration","Phase","Objective","Candidates","Moved row","From","To","Improvement"),trace);resultTab(tabs,"Segmentation starts",List.of("Start","Seed","Search exhausted","Objective","Iterations","Group fits","Failure"),starts);resultTab(tabs,"Diagnostics",List.of("Kind","Message"),diagnostics);SegmentationPlots.add(tabs,result);Label label=new Label("Prediction-oriented segmentation · "+result.options().segments()+" hard groups · "+result.options().criterion()+" · "+(result.converged()?"candidate search exhausted":"provisional solution")+"\nIn-sample optimization is separate from out-of-sample prediction; inspect every start and group size.");label.setWrapText(true);label.setPadding(new Insets(8));resultsTab.setContent(new BorderPane(tabs,label,null,null,null));JsonObject numeric=new JsonObject();numeric.add("pos",new GsonBuilder().serializeSpecialFloatingPointValues().create().toJsonTree(result));lastReport=report("PLS-POS",numeric,result.warnings());}
