    private void beginPairwiseSmoke(Runnable completion){try{var original=projectDocument();var project=syntheticAdvancedProject(false);List<String> names=new ArrayList<>();for(var value:project.getAsJsonArray("columnNames"))names.add(value.getAsString());List<List<String>> rows=new ArrayList<>();int r=0;for(var values:project.getAsJsonArray("observations")){List<String> cells=new ArrayList<>();int c=0;for(var value:values.getAsJsonArray()){cells.add(r==0||(r*9+c)%61==0?"":value.getAsString());c++;}rows.add(cells);r++;}var raw=new DataPreparation.Raw(names,rows);var settings=new DataPreparation.Settings(',',DataPreparation.Decimal.DOT,"NA",DataPreparation.Missing.MEAN_REPLACEMENT);var definitions=names.stream().map(name->new DataPreparation.Column(name,DataPreparation.Kind.NUMERIC)).toList();var prepared=DataPreparation.prepare(raw,settings,definitions);project.add("observations",new Gson().toJsonTree(prepared.values()));project.add("dataPreparation",ImportHistory.capture("Pairwise GUI original source",raw,settings,definitions));load(project,"Pairwise missing-data source");PairwiseDialog.smoke(stage,columnNames,smokeOutput.resolveSibling("pairwise-dialog.png"));bootstrapOptions=new Bootstrap.Options(40,883,.95);pairwiseSmoke(0,()->{try{pairwiseSettings=new PairwiseDialog.Settings(PairwiseDialog.Context.PLS,java.util.stream.IntStream.range(0,9).toArray(),true);bootstrapOptions=new Bootstrap.Options(5000,883,.95);startPairwise(null);var task=activeTask;task.addEventHandler(javafx.concurrent.WorkerStateEvent.WORKER_STATE_CANCELLED,event->Platform.runLater(()->{try{if(lastReport!=null||sidebar.isDisabled())throw new AssertionError("Pairwise cancellation retained partial results");load(original,"Restored after pairwise checks");smokeYield(completion);}catch(Throwable problem){fail(problem);}}));cancelCalculation.fire();}catch(Throwable problem){fail(problem);}});}catch(Throwable problem){fail(problem);}}
