    private void showHierarchyPipeline(HierarchyCalculation result){TabPane tabs=new TabPane();List<String[]> paths=new ArrayList<>(),measurement=new ArrayList<>(),reliability=new ArrayList<>(),correlations=new ArrayList<>(),summary=new ArrayList<>(),warnings=new ArrayList<>();List<String> notes=new ArrayList<>();if(result.composite()!=null){var fit=result.composite();notes.addAll(fit.warnings());summary.add(new String[]{"Estimator","Multi-level composite PLS"});summary.add(new String[]{"Cases",Integer.toString(fit.observations())});summary.add(new String[]{"Original observed columns",Integer.toString(fit.originalColumns())});summary.add(new String[]{"Fitted levels",Integer.toString(fit.stages().size()+1)});for(int level=0;level<fit.stages().size();level++){var stage=fit.stages().get(level);var blocks=stage.secondStageBlocks();for(var edge:stage.specification().edges())paths.add(new String[]{Integer.toString(level+2),blocks.get(edge.source()).name(),blocks.get(edge.target()).name(),format(stage.secondStage().pathCoefficients()[edge.source()][edge.target()]),format(stage.secondStage().rSquared()[edge.target()])});for(var dimension:stage.dimensions())measurement.add(new String[]{Integer.toString(level+2),dimension.name(),dimension.dimension(),dimension.measurementType().name(),format(dimension.weight()),format(dimension.loading())});}}else{var fit=result.factors();notes.addAll(fit.warnings());summary.add(new String[]{"Estimator","Hierarchical PLSc corrected moments"});summary.add(new String[]{"Cases",Integer.toString(fit.observations())});summary.add(new String[]{"Original observed columns",Integer.toString(fit.originalColumns())});summary.add(new String[]{"Fitted levels",Integer.toString(fit.stages().size()+1)});for(int j=0;j<fit.model().blocks().size();j++)reliability.add(new String[]{"1",fit.model().blocks().get(j).name(),format(fit.firstStage().reliabilities()[j]),format(fit.firstStage().rSquared()[j])});for(int level=0;level<fit.stages().size();level++){var stage=fit.stages().get(level);var blocks=stage.blocks();for(var edge:stage.specification().edges())paths.add(new String[]{Integer.toString(level+2),blocks.get(edge.source()).name(),blocks.get(edge.target()).name(),format(stage.paths()[edge.source()][edge.target()]),format(stage.rSquared()[edge.target()])});for(int j=0;j<blocks.size();j++){reliability.add(new String[]{Integer.toString(level+2),blocks.get(j).name(),format(stage.reliabilities()[j]),format(stage.rSquared()[j])});int[] columns=blocks.get(j).columns();for(int k=0;k<columns.length;k++)measurement.add(new String[]{Integer.toString(level+2),blocks.get(j).name(),stage.inputNames().get(columns[k]),blocks.get(j).measurementType().name(),format(stage.weights()[j][k]),format(stage.loadings()[j][k])});for(int k=j+1;k<blocks.size();k++)correlations.add(new String[]{Integer.toString(level+2),blocks.get(j).name(),blocks.get(k).name(),format(stage.correlations()[j][k])});}}}resultTab(tabs,"Hierarchy structural paths",List.of("Level","Source","Target","Coefficient","Target R squared"),paths);resultTab(tabs,"Hierarchy measurement",List.of("Level","Higher-order construct","Input dimension","Measurement","Weight","Loading"),measurement);if(!reliability.isEmpty())resultTab(tabs,"Hierarchy correction / fit",List.of("Level","Construct","rho A (singleton input role = 1)","R squared"),reliability);if(!correlations.isEmpty())resultTab(tabs,"Hierarchy corrected correlations",List.of("Level","Construct","Construct","Corrected correlation"),correlations);List<String[]> effects=new ArrayList<>();var parameters=result.composite()!=null?result.composite().parameters():result.factors().parameters();double[] values=result.composite()!=null?result.composite().estimates():result.factors().estimates();for(int i=0;i<parameters.size();i++)effects.add(new String[]{parameters.get(i).family(),parameters.get(i).label(),format(values[i])});resultTab(tabs,"Final-level targets",List.of("Family","Parameter","Estimate"),effects);if(result.bootstrap()!=null)addExtendedBootstrap(tabs,result.bootstrap(),summary,notes);resultTab(tabs,"Hierarchy pipeline summary",List.of("Quantity","Value"),summary);for(String note:new java.util.LinkedHashSet<>(notes))warnings.add(new String[]{note});resultTab(tabs,"Hierarchy pipeline assumptions",List.of("Assumption / warning"),warnings);Label caption=UiAppearance.label(result.composite()!=null?"Every composite hierarchy level is refitted from the supplied cases. Intermediate score provenance is retained.":"Source and higher-order factor/composite correlations are corrected at their declared levels. No artificial individual factor scores are exposed.");caption.setWrapText(true);resultsTab.setContent(new BorderPane(tabs,caption,null,null,null));Gson gson=new GsonBuilder().serializeNulls().serializeSpecialFloatingPointValues().create();JsonObject numeric=new JsonObject();if(result.composite()!=null)numeric.add("hierarchyPipeline",gson.toJsonTree(result.composite()));else numeric.add("factorHierarchy",gson.toJsonTree(result.factors()));if(result.bootstrap()!=null)numeric.add("bootstrap",gson.toJsonTree(result.bootstrap()));lastReport=report(result.composite()!=null?"HIERARCHY_PIPELINE":"FACTOR_HIERARCHY",numeric,List.copyOf(new java.util.LinkedHashSet<>(notes)));}
