        resultTab(tabs,"Component copula coefficients",List.of("Target","Family","Regressor","Corrected","Uncorrected","Difference"),coefficients);resultTab(tabs,"Component copula diagnostics",List.of("Construct","Distinct","Tied cases","Skewness","Excess kurtosis","Score-normal rank correlation","2sCOPE first-stage R squared","Control overlap R squared"),diagnostics);resultTab(tabs,"Component copula fit",List.of("Quantity","Value"),summary);resultTab(tabs,"Original component paths",List.of("Source","Target","Coefficient","Original R squared","Interpretation"),firstStage);resultTab(tabs,"Generated score controls",List.of("Analysis row","Construct","Generated regressor"),generated);resultTab(tabs,"Corrected score predictions",List.of("Analysis row","Actual unit score","Augmented fitted score","Residual"),predictions);
