    private void showHigherOrder(HigherOrderPls.Fit fit,Bootstrap.Result bootstrap){TabPane tabs=new TabPane();List<String[]> dimensions=new ArrayList<>(),paths=new ArrayList<>(),totals=new ArrayList<>(),specific=new ArrayList<>(),definition=new ArrayList<>(),firstOuter=new ArrayList<>(),secondOuter=new ArrayList<>(),variance=new ArrayList<>(),assumptions=new ArrayList<>();List<String> warnings=new ArrayList<>(fit.warnings());var secondNames=fit.secondStageBlocks().stream().map(PlsSem.Block::name).toList();for(var dimension:fit.dimensions())dimensions.add(new String[]{dimension.name(),dimension.dimension(),dimension.measurementType().name(),dimension.mode().name(),dimension.measurementType()==PlsSem.MeasurementType.REFLECTIVE?"Interpret loading":"Interpret weight",format(dimension.weight()),format(dimension.loading())});for(var effect:fit.effects()){String[] row=new String[]{effect.family(),secondNames.get(effect.source()),secondNames.get(effect.target()),format(effect.value())};if(effect.family().equals("Path"))paths.add(row);else totals.add(row);}for(var effect:fit.specificIndirect())specific.add(new String[]{secondNames.get(effect.source()),secondNames.get(effect.target()),String.join(" → ",effect.route().stream().map(secondNames::get).toList()),format(effect.value())});for(int index=0;index<fit.secondStageBlocks().size();index++){var block=fit.secondStageBlocks().get(index);List<String> indicators=new ArrayList<>();for(int column:block.columns())indicators.add(column<fit.originalColumns()?columnNames.get(column):"Score: "+fit.firstStageBlocks().get(column-fit.originalColumns()).name());definition.add(new String[]{Integer.toString(index),block.name(),block.mode().name(),block.measurementType().name(),String.join("; ",indicators)});}for(int phase=0;phase<2;phase++){var blocks=phase==0?fit.firstStageBlocks():fit.secondStageBlocks();var result=phase==0?fit.firstStage():fit.secondStage();var modelEdges=phase==0?fit.firstStageEdges():fit.specification().edges();double[][] weights=result.weights(),loadings=result.loadings();double[] r2=result.rSquared();for(int block=0;block<blocks.size();block++){int[] columns=blocks.get(block).columns();for(int indicator=0;indicator<columns.length;indicator++){String label=columns[indicator]<fit.originalColumns()?columnNames.get(columns[indicator]):"Score: "+fit.firstStageBlocks().get(columns[indicator]-fit.originalColumns()).name();(phase==0?firstOuter:secondOuter).add(new String[]{blocks.get(block).name(),label,blocks.get(block).mode().name(),blocks.get(block).measurementType().name(),format(weights[block][indicator]),format(loadings[block][indicator])});}int target=block;long parents=modelEdges.stream().filter(edge->edge.target()==target).count();double adjusted=parents==0||!Double.isFinite(r2[block])?Double.NaN:1-(1-r2[block])*(fit.observations()-1)/(fit.observations()-parents-1);variance.add(new String[]{Integer.toString(phase+1),blocks.get(block).name(),Integer.toString(fit.observations()),format(r2[block]),format(adjusted),Integer.toString(result.iterations()),format(result.finalWeightChange())});}}if(bootstrap!=null)warnings.addAll(bootstrap.warnings());for(String warning:new java.util.LinkedHashSet<>(warnings))assumptions.add(new String[]{warning});resultTab(tabs,"Higher-order dimensions",List.of("Higher-order construct","Lower-order dimension","Measurement","Mode","Interpretation","Weight","Loading"),dimensions);resultTab(tabs,"Stage-two structural paths",List.of("Family","Source","Target","Value"),paths);resultTab(tabs,"Stage-two total effects",List.of("Family","Source","Target","Value"),totals);resultTab(tabs,"Stage-two specific indirect effects",List.of("Source","Target","Route","Value"),specific);resultTab(tabs,"Stage-two model definition",List.of("Index","Construct","Mode","Measurement","Indicators"),definition);resultTab(tabs,"Stage-one outer estimates",List.of("Construct","Indicator","Mode","Measurement","Weight","Loading"),firstOuter);resultTab(tabs,"Stage-two outer estimates",List.of("Construct","Indicator / dimension score","Mode","Measurement","Weight","Loading"),secondOuter);resultTab(tabs,"Both-stage explained variance",List.of("Stage","Construct","N","R²","Adjusted R²","Iterations","Final weight change"),variance);resultTab(tabs,"Higher-order assumptions",List.of("Scope / warning"),assumptions);
        if(bootstrap!=null){List<String[]> inference=new ArrayList<>(),accounting=new ArrayList<>();for(var estimate:bootstrap.estimates()){var parameter=estimate.parameter();String label=parameter.label();if(parameter.column()>=0){int column=parameter.column();label=column<fit.originalColumns()?columnNames.get(column):"Score: "+fit.firstStageBlocks().get(column-fit.originalColumns()).name();}inference.add(new String[]{parameter.family(),parameter.source()<0?"—":secondNames.get(parameter.source()),parameter.target()<0?"—":secondNames.get(parameter.target()),label,format(estimate.original()),format(estimate.mean()),format(estimate.standardError()),format(estimate.statistic()),probability(estimate.pValue()),format(estimate.lower()),format(estimate.upper())});}accounting.add(new String[]{"Attempts",Integer.toString(bootstrap.options().samples())});accounting.add(new String[]{"Successful",Integer.toString(bootstrap.successful())});accounting.add(new String[]{"Failed",Integer.toString(bootstrap.failed())});accounting.add(new String[]{"Method",bootstrap.method()});accounting.add(new String[]{"Both-stage score orientation",bootstrap.signHandling()});for(var failure:bootstrap.failures().entrySet())accounting.add(new String[]{failure.getKey(),Integer.toString(failure.getValue())});resultTab(tabs,"Higher-order bootstrap",List.of("Family","Source / construct","Target","Parameter / dimension","Original","Mean","Bootstrap SE","Ratio","Reference P","CI lower","CI upper"),inference);resultTab(tabs,"Higher-order resampling accounting",List.of("Metric / failure","Value"),accounting);}HigherOrderPlots.add(tabs,fit);Label summary=UiAppearance.label("Explicit two-stage higher-order PLS\nDimension loadings/weights are measurement relationships. Full bootstrap refits both stages; exporting the editable stage-two model fixes the first-stage scores for later analyses.");summary.setWrapText(true);summary.setPadding(new Insets(8));resultsTab.setContent(new BorderPane(tabs,summary,null,null,null));JsonObject numeric=new JsonObject();var gson=new GsonBuilder().serializeSpecialFloatingPointValues().create();numeric.add("higherOrderPls",gson.toJsonTree(fit));if(bootstrap!=null)numeric.add("bootstrap",gson.toJsonTree(bootstrap));lastReport=report("DISJOINT_TWO_STAGE_HIGHER_ORDER_PLS",numeric,List.copyOf(new java.util.LinkedHashSet<>(warnings)));}
