    private void startCopula(boolean bootstrap,Runnable completion){var settings=copulaSettings;double[][] source=org.brightstats.stats.Matrices.copy(data);analysisTask(bootstrap?"Resampling ranks, copula stages and structural coefficients...":"Fitting Gaussian-copula control functions...",progress->{int[] columns=settings.predictors();double[][] x=new double[source.length][columns.length];double[] y=new double[source.length];for(int i=0;i<source.length;i++){org.brightstats.stats.Matrices.interrupted();for(int j=0;j<columns.length;j++)x[i][j]=source[i][columns[j]];y[i]=source[i][settings.response()];}if(!bootstrap)return new CopulaCalculation(CopulaRegression.fit(x,y,settings.model()),null);var result=CopulaRegression.bootstrap(x,y,settings.model(),settings.bootstrap(),progress);return new CopulaCalculation(result.point(),result.inference());},result->{lastFit=null;lastDiagnostics=null;lastBootstrap=null;showCopula(result.point(),result.inference());status.setText("Copula estimation completed; inspect identification diagnostics and assumptions.");if(completion!=null)completion.run();});}
