    private void startProcess(boolean bootstrap,Runnable completion){var settings=processSettings;double[][] source=org.brightstats.stats.Matrices.copy(data);var names=List.copyOf(columnNames);analysisTask(bootstrap?"Resampling conditional path models...":"Fitting observed-variable path equations...",progress->{if(!bootstrap)return new ProcessCalculation(PathProcess.fit(source,names,settings.model(),settings.options(),settings.probes()),null);var result=PathProcess.bootstrap(source,names,settings.model(),settings.options(),settings.probes(),settings.bootstrap(),progress);return new ProcessCalculation(result.point(),result.inference());},result->{lastFit=null;lastDiagnostics=null;lastBootstrap=null;showProcess(result.point(),result.inference(),source);status.setText("Conditional process estimation completed."+(result.inference()==null?"":" "+result.inference().successful()+" successful paired samples."));if(completion!=null)completion.run();});}
