    private void showProcess(PathProcess.Fit fit,Bootstrap.Result bootstrap,double[][] original,JsonObject analysisProject){
        TabPane tabs=new TabPane();List<String[]> coefficients=new ArrayList<>(),equations=new ArrayList<>(),paths=new ArrayList<>(),effects=new ArrayList<>(),probes=new ArrayList<>(),transforms=new ArrayList<>(),specification=new ArrayList<>(),diagnostics=new ArrayList<>();List<String> warnings=new ArrayList<>(fit.warnings());for(var equation:fit.equations()){var ordinary=equation.ordinary();equations.add(new String[]{fit.names().get(equation.response()),Integer.toString(ordinary.observations()),Integer.toString(ordinary.residualDegreesOfFreedom()),format(ordinary.rSquared()),format(ordinary.adjustedRSquared()),format(ordinary.residualSumOfSquares()),equation.inference().covariance().name()});for(int index=0;index<equation.inference().terms().size();index++){String label=index==0?"Intercept":String.join(" × ",Arrays.stream(equation.predictors().get(index-1).columns()).mapToObj(fit.names()::get).toList());var term=equation.inference().terms().get(index);coefficients.add(new String[]{fit.names().get(equation.response()),label,format(term.estimate()),format(term.standardError()),format(term.statistic()),probability(term.pValue()),format(term.lower()),format(term.upper())});}}for(var path:fit.conditionalPaths()){var term=path.inference();paths.add(new String[]{path.probe(),fit.names().get(path.source()),fit.names().get(path.target()),format(term.estimate()),format(term.standardError()),format(term.statistic()),probability(term.pValue()),format(term.lower()),format(term.upper())});}for(var effect:fit.effects())effects.add(new String[]{effect.probe(),effect.family(),effect.label(),format(effect.value()),"Indirect/derivative uncertainty requires paired bootstrap"});for(var probe:fit.probes())for(var value:probe.values().entrySet())probes.add(new String[]{probe.name(),fit.names().get(value.getKey()),format(value.getValue())});double[] means=fit.means(),centers=fit.centers(),scales=fit.scales();for(int column=0;column<means.length;column++)if(Double.isFinite(means[column]))transforms.add(new String[]{fit.names().get(column),format(means[column]),format(centers[column]),format(scales[column])});for(var path:fit.model().paths())specification.add(new String[]{fit.names().get(path.source()),fit.names().get(path.target()),String.join(", ",Arrays.stream(path.moderators()).mapToObj(fit.names()::get).toList())});if(bootstrap!=null)warnings.addAll(bootstrap.warnings());for(var message:warnings)diagnostics.add(new String[]{"Assumption / diagnostic",message});
        resultTab(tabs,"Equation coefficients",List.of("Response","Predictor","Estimate","SE","T / Z","P","CI lower","CI upper"),coefficients);resultTab(tabs,"Equation fit",List.of("Response","N","Residual df","R²","Adjusted R²","Residual SS","Covariance"),equations);resultTab(tabs,"Conditional paths",List.of("Probe","Source","Target","Effect","SE","T / Z","P","CI lower","CI upper"),paths);resultTab(tabs,"Conditional effects",List.of("Probe","Family","Route / definition","Estimate","Uncertainty"),effects);resultTab(tabs,"Moderator probes",List.of("Probe","Moderator","Original-unit value"),probes);resultTab(tabs,"Data transformations",List.of("Variable","Raw mean","Subtracted center","Divisor"),transforms);resultTab(tabs,"Process model",List.of("Source","Target","Exogenous moderators"),specification);resultTab(tabs,"Diagnostics",List.of("Kind","Message"),diagnostics);
        if(bootstrap!=null){List<String[]> inference=new ArrayList<>(),accounting=new ArrayList<>();for(var estimate:bootstrap.estimates()){var selected=estimate.interval();var corrected=estimate.correctedInterval();inference.add(new String[]{estimate.parameter().family(),estimate.parameter().label(),format(estimate.original()),format(estimate.mean()),format(estimate.standardError()),format(estimate.statistic()),probability(estimate.pValue()),format(selected.lower()),format(selected.upper()),format(corrected.lower()),format(corrected.upper())});}accounting.add(new String[]{"Attempted",Integer.toString(bootstrap.options().samples())});accounting.add(new String[]{"Successful",Integer.toString(bootstrap.successful())});accounting.add(new String[]{"Failed",Integer.toString(bootstrap.failed())});accounting.add(new String[]{"Method",bootstrap.method()});for(var failure:bootstrap.failures().entrySet())accounting.add(new String[]{failure.getKey(),Integer.toString(failure.getValue())});resultTab(tabs,"Process bootstrap",List.of("Family","Parameter / probe","Original","Mean","SE","Ratio","P","Selected CI lower","Selected CI upper","Corrected CI lower","Corrected CI upper"),inference);resultTab(tabs,"Bootstrap accounting",List.of("Metric / reason","Value"),accounting);}
        ProcessPlots.add(tabs,fit,original);Label summary=new Label("Observed-variable conditional process · "+fit.options().metric()+" · "+fit.options().covariance()+" · "+fit.names().get(fit.model().source())+" → "+fit.names().get(fit.model().target())+"\nPaired bootstrap is required for indirect-effect uncertainty. Conditional associations alone do not establish causality.");summary.setWrapText(true);summary.setPadding(new Insets(8));resultsTab.setContent(new BorderPane(tabs,summary,null,null,null));JsonObject numeric=new JsonObject();var gson=new GsonBuilder().serializeSpecialFloatingPointValues().create();numeric.add("process",gson.toJsonTree(fit));if(bootstrap!=null)numeric.add("bootstrap",gson.toJsonTree(bootstrap));lastReport=report("PROCESS",numeric,warnings);if(analysisProject!=null)lastReport.add("project",analysisProject.deepCopy());
    }
