        TabPane tabs=new TabPane();List<String[]> terms=new ArrayList<>(),blocks=new ArrayList<>(),diagnostics=new ArrayList<>(),histograms=new ArrayList<>();List<String> warnings=new ArrayList<>(fit.warnings());for(var message:fit.warnings())diagnostics.add(new String[]{"All blocks","Assumption",message});for(var skipped:fit.skipped())diagnostics.add(new String[]{"Skipped","Ineligible block",skipped});for(var block:fit.blocks()){String verdict=block.rejectsReflective()?"Reflective restrictions challenged":block.terms().stream().anyMatch(term->!term.intervalAvailable())?"Inference incomplete":"No rejection (not proof of reflectivity)";blocks.add(new String[]{block.name(),Integer.toString(block.columns().length),Integer.toString(block.terms().size()),Integer.toString(block.fullTetradCount()),Integer.toString(block.genericOneFactorCodimension()),verdict});for(var warning:block.warnings()){warnings.add(block.name()+": "+warning);diagnostics.add(new String[]{block.name(),"Diagnostic",warning});}for(var term:block.terms()){terms.add(new String[]{block.name(),Integer.toString(term.tetrad().id()),term.label(),format(term.original()),format(term.mean()),format(term.standardDeviation()),format(term.statistic()),probability(term.pValue()),probability(term.bonferroniP()),format(term.bias()),format(term.lower()),format(term.upper()),format(term.adjustedSignificance()),format(term.adjustedCritical()),format(term.adjustedLower()),format(term.adjustedUpper()),format(term.percentileLower()),format(term.percentileUpper()),term.intervalAvailable()?term.adjustedIntervalRejects()?"Adjusted interval excludes zero":"Adjusted interval includes zero":"Interval unavailable"});var histogram=term.histogram();double[] breaks=histogram.breaks();int[] counts=histogram.counts();for(int bin=0;bin<counts.length;bin++)histograms.add(new String[]{block.name(),Integer.toString(term.tetrad().id()),format(breaks[bin]),format(breaks[bin+1]),Integer.toString(counts[bin])});}}
        resultTab(tabs,"Tetrad inference",List.of("Block","ID","Indicator quartet","Original","Bootstrap mean","Bootstrap SD","|T|","P","Bonferroni P","Bias","CI lower","CI upper","Adjusted alpha","Adjusted critical","Adjusted CI lower","Adjusted CI upper","Percentile lower","Percentile upper","Interval assessment"),terms);resultTab(tabs,"Block assessment",List.of("Block","Indicators","Reported tests","All tetrads","Generic codimension","Assessment"),blocks);resultTab(tabs,"Tetrad histograms",List.of("Block","ID","Bin lower","Bin upper","Count"),histograms);resultTab(tabs,"Diagnostics",List.of("Block","Kind","Message"),diagnostics);Label summary=new Label("CTA · "+fit.successful()+" of "+fit.options().samples()+" paired bootstrap samples · "+fit.options().selection()+" · "+fit.options().convention()+"\nBonferroni adjustment is within each block. Nonrejection does not establish reflectivity or causality.\n"+String.join("\n",warnings));summary.setWrapText(true);summary.setPadding(new Insets(8));resultsTab.setContent(new BorderPane(tabs,summary,null,null,null));JsonObject numeric=new JsonObject();numeric.add("tetrads",new GsonBuilder().serializeSpecialFloatingPointValues().create().toJsonTree(fit));lastReport=report("CTA-PLS",numeric,warnings);
