    private void bootstrapResultTab(TabPane tabs,Bootstrap.Result inference){bootstrapResultTab(tabs,inference,false);}
    private void bootstrapResultTab(TabPane tabs,Bootstrap.Result inference,boolean directLabels){
        List<String[]> rows=new ArrayList<>(),corrected=new ArrayList<>();
        boolean reference=inference.options().convention()==RegressionBootstrap.Convention.REFERENCE_4_1_2_1;
        boolean accelerated=reference&&inference.options().interval()==BootstrapIntervals.Method.BCA;
        for(var estimate:inference.estimates()){
            var parameter=estimate.parameter();String label=directLabels||parameter.column()<0?parameter.label():constructs.get(parameter.source()).name+" / "+columnNames.get(parameter.column());
            rows.add(new String[]{parameter.family(),label,format(estimate.original()),format(estimate.mean()),format(estimate.standardError()),format(estimate.statistic()),probability(estimate.pValue()),format(estimate.lower()),format(estimate.upper()),String.join("; ",estimate.interval().warnings())});
            var interval=estimate.correctedInterval();corrected.add(new String[]{parameter.family(),label,format(estimate.original()),format(interval.lower()),format(interval.upper()),String.join("; ",interval.warnings())});
        }
        resultTab(tabs,"Bootstrap inference",List.of("Estimate","Parameter","Original","Bootstrap mean","SE","|Estimate / SE|",reference?"P (reference t)":"P (normal, 2-sided)",accelerated?"Percentile lower":"CI lower",accelerated?"Percentile upper":"CI upper","Interval notes"),rows);
        resultTab(tabs,accelerated?"BCa intervals (reference)":"Bootstrap corrected intervals",List.of("Estimate","Parameter","Original","Corrected lower","Corrected upper","Notes"),corrected);
    }
    private void bootstrap() {
        if(data.length==0 || constructs.isEmpty())throw new IllegalArgumentException("Import data and define a model first.");
        var settings=BootstrapDialog.show(stage,bootstrapOptions); if(settings.isEmpty())return;
        bootstrapOptions=settings.get(); dirty=true; startBootstrap(null);
    }
    private void startBootstrap(Runnable completion) {
        var blocks=constructs.stream().map(c->new PlsSem.Block(c.name,c.columns,c.mode,c.initialWeights,c.measurementType)).toList();
        var structure=List.copyOf(edges); double[][] observations=data; var settings=bootstrapOptions; var modelOptions=calculationOptions;
        lastReport=null; lastBootstrap=null; status.setText("Bootstrapping 0 / "+settings.samples()+"...");
        Task<BootstrapCalculation> task=new Task<>() {
            @Override protected BootstrapCalculation call() {
                var original=PlsSem.fit(observations,blocks,structure,modelOptions);
                var inference=Bootstrap.fit(observations,blocks,structure,modelOptions,settings,done -> {updateProgress(done,settings.samples());updateMessage("Bootstrapping "+done+" / "+settings.samples()+"...");});
                return new BootstrapCalculation(new Calculation(original,ModelDiagnostics.compute(observations,blocks,structure,original)),inference);
            }
        };
        beginTask(task); task.messageProperty().addListener((o,a,b)->{if(activeTask==task)status.setText(b);});
        task.setOnSucceeded(event -> { endTask(); lastFit=task.getValue().calculation().model(); lastDiagnostics=task.getValue().calculation().diagnostics(); lastBootstrap=task.getValue().inference(); showPlsResults(); draw(); workspace.getSelectionModel().select(resultsTab); status.setText("Bootstrap completed: "+lastBootstrap.successful()+" successful; "+lastBootstrap.failed()+" failed."); if(completion!=null)completion.run(); });
        task.setOnFailed(event -> { endTask(); fail(task.getException()); }); dispatchCalculation(task);
    }
    private void showPlsResults() {
        TabPane results = new TabPane();
        List<String[]> paths = new ArrayList<>(); double[][] coefficients = lastFit.pathCoefficients();
        double[][] f2 = lastDiagnostics == null ? null : lastDiagnostics.effectSizes();
        double[][] vif = lastDiagnostics == null ? null : lastDiagnostics.innerVif();
        for (var edge : edges) paths.add(new String[]{constructs.get(edge.source()).name, constructs.get(edge.target()).name, format(coefficients[edge.source()][edge.target()]),
                f2 == null ? "—" : format(f2[edge.source()][edge.target()]), vif == null ? "—" : format(vif[edge.source()][edge.target()])});
        resultTab(results, "Paths", List.of("From", "To", "Coefficient", "f²", "VIF"), paths);
        List<String[]> weights = new ArrayList<>(), loadings = new ArrayList<>();
        double[][] w = lastFit.weights(), l = lastFit.loadings();
        for (int j = 0; j < constructs.size(); j++) {
            Construct node = constructs.get(j);
            for (int k = 0; k < node.columns.length; k++) {
                weights.add(new String[]{node.name, columnNames.get(node.columns[k]), format(w[j][k])});
                loadings.add(new String[]{node.name, columnNames.get(node.columns[k]), format(l[j][k])});
            }
        }
        resultTab(results, "Weights", List.of("Construct", "Indicator", "Weight"), weights);
        resultTab(results, "Loadings", List.of("Construct", "Indicator", "Loading"), loadings);
        List<String[]> quality = new ArrayList<>(); double[] r2 = lastFit.rSquared();
        for (int j = 0; j < constructs.size(); j++) quality.add(new String[]{constructs.get(j).name, format(r2[j])});
        resultTab(results, "R-square", List.of("Construct", "R-square"), quality);
        if (lastDiagnostics != null) {
            List<String[]> reliability = new ArrayList<>(), outerVif = new ArrayList<>();
            var statistics = lastDiagnostics.reliability(); double[][] outer = lastDiagnostics.outerVif();
            for (int j = 0; j < constructs.size(); j++) {
                var stat = statistics[j]; Construct construct = constructs.get(j);
                reliability.add(new String[]{construct.name, construct.measurementType == PlsSem.MeasurementType.REFLECTIVE ? "Reflective" : "Formative",
                        format(stat.alpha()), format(stat.rhoA()), format(stat.rhoC()), format(stat.ave())});
                for (int k = 0; k < construct.columns.length; k++) outerVif.add(new String[]{construct.name, columnNames.get(construct.columns[k]), format(outer[j][k])});
            }
            resultTab(results, "Reliability", List.of("Construct", "Measurement", "Alpha", "rho_A", "rho_C", "AVE"), reliability);
            resultTab(results, "Outer VIF", List.of("Construct", "Indicator", "VIF"), outerVif);
            matrixTab(results, "HTMT", lastDiagnostics.htmt());
            matrixTab(results, "Fornell-Larcker", lastDiagnostics.fornellLarcker());
            matrixTab(results, "Total effects", lastDiagnostics.totalEffects());
            matrixTab(results, "Indirect effects", lastDiagnostics.indirectEffects());
            List<String[]> cross = new ArrayList<>(); double[][] crossValues = lastDiagnostics.crossLoadings();
            for (int j = 0; j < crossValues.length; j++) {
                if (Arrays.stream(crossValues[j]).noneMatch(Double::isFinite)) continue;
                String[] row = new String[constructs.size() + 1]; row[0] = columnNames.get(j);
                for (int k = 0; k < constructs.size(); k++) row[k + 1] = format(crossValues[j][k]);
                cross.add(row);
            }
            List<String> names = new ArrayList<>(); names.add("Indicator"); names.addAll(constructs.stream().map(c -> c.name).toList());
            resultTab(results, "Cross loadings", names, cross);
        }
        resultsTab.setContent(results);
        if(lastBootstrap!=null) {
            bootstrapResultTab(results,lastBootstrap);
            Tab inferenceTab=results.getTabs().getLast();
            Label summary=new Label((lastBootstrap.options().confidence()*100)+"% nominal confidence · "+lastBootstrap.options().convention()+" · "+lastBootstrap.options().interval()+" · seed "+lastBootstrap.options().seed()+" · "+lastBootstrap.successful()+" successful / "+lastBootstrap.options().samples()+" attempts\n"
                    + String.join("\n",lastBootstrap.warnings()) + (lastBootstrap.failed()>0?"\nFailure reasons: "+lastBootstrap.failures():""));
            summary.setWrapText(true); summary.setPadding(new Insets(8));
            inferenceTab.setContent(new BorderPane(inferenceTab.getContent(),summary,null,null,null));
        }
        if (lastDiagnostics != null && !lastDiagnostics.warnings().isEmpty()) {
            Label warning = new Label(String.join("\n", lastDiagnostics.warnings())); warning.setWrapText(true);
            resultsTab.setContent(new BorderPane(results, warning, null, null, null));
        }
        var gson = new GsonBuilder().serializeSpecialFloatingPointValues().create();
        JsonObject numeric = new JsonObject(); numeric.add("fit", gson.toJsonTree(lastFit));
        if(lastBootstrap!=null)numeric.add("bootstrap",gson.toJsonTree(lastBootstrap));
        if (lastDiagnostics != null) numeric.add("diagnostics", gson.toJsonTree(lastDiagnostics));
        List<String> warnings = new ArrayList<>();
        if (!lastFit.converged()) warnings.add("Iteration limit reached; estimates are provisional.");
        if (lastDiagnostics != null) warnings.addAll(lastDiagnostics.warnings());
        if(lastBootstrap!=null)warnings.addAll(lastBootstrap.warnings());
        if(lastBootstrap!=null && importHistory!=null && importHistory.get("replacedCells").getAsInt()>0)
            warnings.add("Bootstrap resamples the already prepared data; uncertainty from missing-value imputation is not included.");
        lastReport = report("PLS-SEM", numeric, warnings);
    }
    private void predictiveValidation() {
        if(data.length==0||constructs.isEmpty())throw new IllegalArgumentException("Import data and define a model first.");
        var chosen=PredictionDialog.showWithInference(stage,predictionOptions,predictionInferenceConfidence);if(chosen.isEmpty())return;predictionOptions=chosen.get().prediction();predictionInferenceConfidence=chosen.get().confidence();dirty=true;startPrediction(null);
    }
    private void startPrediction(Runnable completion) {
        var blocks=constructs.stream().map(c->new PlsSem.Block(c.name,c.columns,c.mode,c.initialWeights,c.measurementType)).toList();var structure=List.copyOf(edges);var settings=predictionOptions;var modelOptions=calculationOptions;
        double[][] original=PredictionInput.original(importHistory,columnNames,data);String source=importHistory==null?"Project numeric observations":"Original numeric source cells reconstructed before imputation; retained project row mapping applied";
        int total=settings.repeats()*(settings.scheme()==Prediction.Scheme.K_FOLD?settings.folds():1);lastReport=null;lastBootstrap=null;status.setText("Validating predictions 0 / "+total+"...");
        double confidence=predictionInferenceConfidence;Task<PredictionCalculation> task=new Task<>(){@Override protected PredictionCalculation call(){var point=Prediction.evaluate(original,blocks,structure,modelOptions,settings,done->{updateProgress(done,total);updateMessage("Validating predictions "+done+" / "+total+"...");});return new PredictionCalculation(point,PredictionInference.evaluate(point,confidence));}};
        beginTask(task);task.messageProperty().addListener((o,a,b)->{if(activeTask==task)status.setText(b);});
        task.setOnSucceeded(event->{endTask();showPrediction(task.getValue().point(),source,task.getValue().inference());status.setText("Predictive validation completed: "+task.getValue().point().predictions().size()+" held-out forecasts.");if(completion!=null)completion.run();});
        task.setOnFailed(event->{endTask();fail(task.getException());});dispatchCalculation(task);
    }
    private String predictionTarget(Prediction.Target target){return constructs.get(target.construct()).name+" / "+columnNames.get(target.column());}
    private void showPrediction(Prediction.Result result,String source,PredictionInference.Result inference) {
        TabPane tabs=new TabPane();List<String> headers=List.of("Target","Observed","PLS RMSE","PLS MAE","Mean RMSE","Mean MAE","Linear RMSE","Linear MAE","Q²predict");
        List<String[]> summaries=new ArrayList<>();for(var metric:result.metrics())summaries.add(predictionMetric(metric,false));resultTab(tabs,"Prediction metrics",headers,summaries);
        List<String> foldHeaders=new ArrayList<>(List.of("Repeat","Fold"));foldHeaders.addAll(headers);List<String[]> folds=new ArrayList<>();for(var metric:result.foldMetrics())folds.add(predictionMetric(metric,true));resultTab(tabs,"Fold metrics",foldHeaders,folds);
        List<String[]> rows=new ArrayList<>();for(var row:result.predictions())rows.add(new String[]{Integer.toString(row.repeat()),Integer.toString(row.fold()),Integer.toString(row.row()),predictionTarget(result.targets().get(row.target())),format(row.actual()),format(row.pls()),format(row.mean()),format(row.linear()),format(row.actual()-row.pls())});
        resultTab(tabs,"Held-out predictions",List.of("Repeat","Fold","Analysis row","Target","Actual","PLS","Mean benchmark","Linear benchmark","PLS residual"),rows);
        List<String[]> assignments=new ArrayList<>();int[][] split=result.assignments();for(int repeat=0;repeat<split.length;repeat++)for(int row=0;row<split[repeat].length;row++)assignments.add(new String[]{Integer.toString(repeat+1),Integer.toString(row+1),Integer.toString(split[repeat][row])});
        resultTab(tabs,"Fold assignments",List.of("Repeat","Analysis row","Test fold (0 = training-only holdout)"),assignments);
        List<String[]> errors=new ArrayList<>();for(var metric:inference.metrics())errors.add(new String[]{predictionTarget(result.targets().get(metric.target())),Integer.toString(metric.forecasts()),Integer.toString(metric.zeroActual()),Integer.toString(metric.nearZeroActual()),Integer.toString(metric.percentageObservations()),format(metric.mape()),format(metric.smape()),format(metric.medianAbsoluteError()),format(metric.percentile95AbsoluteError()),format(metric.relativeMae())});resultTab(tabs,"Percentage and robust errors",List.of("Target","Forecasts","Zero actual","Near-zero actual","MAPE usable","MAPE %","SMAPE %","Median absolute error","95th percentile error","Relative MAE vs mean"),errors);List<String[]> tests=new ArrayList<>();for(var comparison:inference.comparisons()){String scope=comparison.scope().equals("INDICATOR")?predictionTarget(result.targets().get(comparison.target())):comparison.scope().equals("CONSTRUCT")?"Construct "+(comparison.construct()+1):"All endogenous indicators";tests.add(new String[]{scope,comparison.benchmark().toString(),Integer.toString(comparison.observations()),format(comparison.plsLoss()),format(comparison.benchmarkLoss()),format(comparison.meanDifference()),format(comparison.standardError()),format(comparison.statistic()),Integer.toString(comparison.degreesOfFreedom()),probability(comparison.pOneSided()),probability(comparison.pHolm()),format(comparison.lower()),format(comparison.upper()),format(comparison.upperOneSided()),comparison.status()});}resultTab(tabs,"CVPAT",List.of("Scope","Benchmark","Paired cases","PLS loss","Benchmark loss","Loss difference","SE","T","df","P one-sided","P Holm","Two-sided lower","Two-sided upper","One-sided upper","Status"),tests);List<String[]> notices=new ArrayList<>();for(String warning:inference.warnings())notices.add(new String[]{warning});resultTab(tabs,"Prediction diagnostics",List.of("Assumption / diagnostic"),notices);
        Label summary=new Label(result.options().scheme()+" · "+result.options().repeats()+" repeats · seed "+result.options().seed()+"\nTraining-only preprocessing; held-out endogenous indicators are never predictors. RMSE/MAE in original units; lower is better.\n"+String.join("\n",result.warnings()));summary.setWrapText(true);summary.setPadding(new Insets(8));resultsTab.setContent(new BorderPane(tabs,summary,null,null,null));workspace.getSelectionModel().select(resultsTab);
        var gson=new GsonBuilder().serializeSpecialFloatingPointValues().create();JsonObject numeric=new JsonObject();numeric.add("prediction",gson.toJsonTree(result));numeric.add("predictiveTests",gson.toJsonTree(inference));numeric.addProperty("inputSource",source);List<String> combinedWarnings=new ArrayList<>(result.warnings());combinedWarnings.addAll(inference.warnings());lastReport=report("PLS-PREDICT",numeric,combinedWarnings);
    }
    private String[] predictionMetric(Prediction.Metric metric,boolean withFold) {
        List<String> cells=new ArrayList<>();if(withFold){cells.add(Integer.toString(metric.repeat()));cells.add(Integer.toString(metric.fold()));}
        cells.addAll(List.of(predictionTarget(metric.target()),Integer.toString(metric.observations()),format(metric.plsRmse()),format(metric.plsMae()),format(metric.meanRmse()),format(metric.meanMae()),format(metric.linearRmse()),format(metric.linearMae()),format(metric.qSquaredPredict())));return cells.toArray(String[]::new);
    }
    private void matrixTab(TabPane results, String title, double[][] values) {
        List<String> names = new ArrayList<>(); names.add("Construct"); names.addAll(constructs.stream().map(c -> c.name).toList());
        List<String[]> rows = new ArrayList<>();
        for (int j = 0; j < values.length; j++) {
            String[] row = new String[values[j].length + 1]; row[0] = constructs.get(j).name;
            for (int k = 0; k < values[j].length; k++) row[k + 1] = format(values[j][k]); rows.add(row);
        }
        resultTab(results, title, names, rows);
    }
    private void regress() {
        if (data.length == 0) throw new IllegalArgumentException("Import data first");
        var selection=RegressionDialog.show(stage,columnNames,false,regressionCovariance,regressionConfidence);if(selection.isEmpty())return;var settings=selection.get();regressionConfidence=settings.confidence();regressionCovariance=settings.covariance();dirty=true;calculateRegression(settings.response(),settings.predictors());
    }
    private void calculateRegression(int dependent, int[] columns) {
        if (Arrays.stream(columns).anyMatch(c -> c == dependent)) throw new IllegalArgumentException("Response cannot also be a predictor");
        lastReport = null;
        double[][] x = new double[data.length][columns.length]; double[] y = new double[data.length];
        for (int i = 0; i < data.length; i++) { y[i] = data[i][dependent]; for (int j = 0; j < columns.length; j++) x[i][j] = data[i][columns[j]]; }
        var warnings = selectedWarnings(columns);
        if (!warnings.isEmpty()) throw new IllegalArgumentException(String.join("\n", warnings));
        var robust=RobustRegression.fit(x,y,regressionCovariance,regressionConfidence);var fit=robust.ordinary();var inference=new Inference.Regression(regressionConfidence,fit.residualDegreesOfFreedom(),robust.inferenceMethod(),robust.terms());List<String[]> rows = new ArrayList<>();
        double[] coefficients = fit.coefficients();
        for (int j = 0; j < coefficients.length; j++) {
            var term=inference.terms().get(j);
            rows.add(new String[]{j == 0 ? "Intercept" : columnNames.get(columns[j - 1]), format(coefficients[j]), format(term.standardError()),format(term.statistic()),probability(term.pValue()),format(term.lower()),format(term.upper())});
        }
        VBox result = new VBox(12, new Label("Response: " + columnNames.get(dependent)),
                new Label("R-square: " + format(fit.rSquared()) + "    Adjusted R-square: " + format(fit.adjustedRSquared())),
                new Label((regressionConfidence*100)+"% confidence · residual df="+fit.residualDegreesOfFreedom()+" · "+robust.inferenceMethod()+" · "+regressionCovariance),
                table(List.of("Term", "Coefficient", "Standard error",regressionCovariance==RobustRegression.Covariance.CLASSICAL?"T":"Z","P (2-sided)","CI lower","CI upper"), rows)); result.setPadding(new Insets(18));
        resultsTab.setContent(result); workspace.getSelectionModel().select(resultsTab);
        JsonObject numeric = new JsonObject();
        var gson = new GsonBuilder().serializeSpecialFloatingPointValues().create();
        numeric.addProperty("response", columnNames.get(dependent));
        numeric.add("predictors", gson.toJsonTree(Arrays.stream(columns).mapToObj(columnNames::get).toList()));
        numeric.add("fit", gson.toJsonTree(fit));
        numeric.add("inference",gson.toJsonTree(inference));
        numeric.add("robust",gson.toJsonTree(robust));lastReport = report("OLS", numeric, robust.warnings());
        status.setText("Regression completed for " + fit.observations() + " observations.");
    }
