        Label summary=new Label("Response: "+columnNames.get(dependent)+" · "+fit.options().interval()+" · "+fit.successful()+" successful / "+fit.options().samples()+" attempted\n"+String.join("\n",fit.warnings()));summary.setWrapText(true);summary.setPadding(new Insets(8));resultsTab.setContent(new BorderPane(tabs,summary,null,null,null));var gson=new GsonBuilder().serializeSpecialFloatingPointValues().create();JsonObject numeric=new JsonObject();numeric.addProperty("response",columnNames.get(dependent));numeric.add("predictors",gson.toJsonTree(Arrays.stream(columns).mapToObj(columnNames::get).toList()));numeric.add("regressionBootstrap",gson.toJsonTree(fit));lastReport=report("REGRESSION_BOOTSTRAP",numeric,fit.warnings());
