    private int hit(double x, double y) {
        for (int i = constructs.size() - 1; i >= 0; i--) {
            Construct node = constructs.get(i);double[] frame=modelMotion==null?null:modelMotion.positions().get(i); if (ModelDiagramGraphics.hit(x,y,frame==null?node.x:frame[0],frame==null?node.y:frame[1])) return i;
        }
        return -1;
    }
    private void arrange() {
        int count = constructs.size();
        if (count == 0) return;
        Map<Integer,double[]> animationStart=new java.util.LinkedHashMap<>();for(int i=0;i<count;i++)animationStart.put(i,new double[]{constructs.get(i).x,constructs.get(i).y});
        int[] level = new int[count], degree = new int[count];
        for (var edge : edges) degree[edge.target()]++;
        List<Integer> ready = new ArrayList<>();
        for (int i = 0; i < count; i++) if (degree[i] == 0) ready.add(i);
        for (int i = 0; i < ready.size(); i++) {
            int node = ready.get(i);
            for (var edge : edges) if (edge.source() == node) {
                level[edge.target()] = Math.max(level[edge.target()], level[node] + 1);
                if (--degree[edge.target()] == 0) ready.add(edge.target());
            }
        }
        if (ready.size() != count) throw new IllegalArgumentException("Remove directed cycles before arranging this model");
        int maximum = Arrays.stream(level).max().orElse(0);
        for (int layer = 0; layer <= maximum; layer++) {
            List<Integer> group = new ArrayList<>();
            for (int j = 0; j < count; j++) if (level[j] == layer) group.add(j);
            for (int j = 0; j < group.size(); j++) {
                Construct node = constructs.get(group.get(j));
                node.x = 115 + layer * Math.min(240, 1250.0 / Math.max(1, maximum));
                node.y = (j + 1) * 600.0 / (group.size() + 1);
            }
        }
        if(modelMotion!=null){Map<Integer,double[]> target=new java.util.LinkedHashMap<>();for(int i=0;i<count;i++)target.put(i,new double[]{constructs.get(i).x,constructs.get(i).y});modelMotion.arrange(animationStart,target);}
    }
    private List<ModelDiagramGraphics.Node> diagramNodes(){List<ModelDiagramGraphics.Node> nodes=new ArrayList<>();for(int i=0;i<constructs.size();i++){var node=constructs.get(i);double[] frame=modelMotion==null?null:modelMotion.positions().get(i);nodes.add(new ModelDiagramGraphics.Node(node.name,node.columns.length,node.mode.name(),frame==null?node.x:frame[0],frame==null?node.y:frame[1],i==selected||selection.contains(i)));}return List.copyOf(nodes);}
    private List<ModelDiagramGraphics.Edge> diagramEdges(){double[][] coefficients=lastFit==null?null:lastFit.pathCoefficients();return edges.stream().map(edge->new ModelDiagramGraphics.Edge(edge.source(),edge.target(),coefficients!=null&&Double.isFinite(coefficients[edge.source()][edge.target()])?coefficients[edge.source()][edge.target()]:null)).toList();}
    private String diagramSvg(String title){if(modelMotion!=null)modelMotion.finish();return ModelDiagramGraphics.svg(diagram.getWidth(),diagram.getHeight(),diagramNodes(),diagramEdges(),ModelDiagramGraphics.palette(UiAppearance.theme(),UiAppearance.current().accent()),UiAppearance.current().showGrid(),diagramDocument(),title);}
    private void draw(){if(modelViewport!=null)modelViewport.display(UiAppearance.current().showGrid(),UiAppearance.current().snapToGrid());var nodes=diagramNodes();ModelDiagramGraphics.draw(diagram,nodes,diagramEdges(),ModelDiagramGraphics.palette(UiAppearance.theme(),UiAppearance.current().accent()),UiAppearance.current().showGrid());if(modelViewport!=null)modelViewport.geometry(nodes.stream().map(n->new ModelViewport.Point(n.x(),n.y(),n.name(),n.selected())).toList(),edges.stream().map(e->new ModelViewport.Edge(e.source(),e.target())).toList());}
    private double dragPosition(double value,double minimum,double maximum){if(modelViewport!=null&&modelViewport.snap()){double low=Math.ceil((minimum-20)/24),high=Math.floor((maximum-20)/24);return 20+24*Math.max(low,Math.min(high,Math.rint((value-20)/24)));}return Math.max(minimum,Math.min(maximum,value));}
