    private void finishBootstrapSmoke(int panels,int iterations) {
        try {
            if(lastBootstrap==null || lastBootstrap.successful()!=80 || lastBootstrap.failed()!=0)throw new AssertionError("Bootstrap background task failed");
            JsonObject archive=lastReport.deepCopy(); var options=bootstrapOptions;
            if(archive.getAsJsonArray("tables").size()!=13)throw new AssertionError("Bootstrap inference table missing");
            Path saved=smokeOutput.resolveSibling("bootstrap.bsreport.json"); ReportArchive.write(saved,archive);
            JsonObject reopened=ReportArchive.read(saved);
            if(!archive.equals(reopened) || reopened.getAsJsonObject("results").getAsJsonObject("bootstrap").getAsJsonObject("options").get("seed").getAsLong()!=Long.MAX_VALUE)throw new AssertionError("Bootstrap archive/seed changed");
            ReportArchive.writeHtml(smokeOutput.resolveSibling("bootstrap.html"),reopened);
            TabPane tabs=resultsTab.getContent() instanceof TabPane pane?pane:(TabPane)((BorderPane)resultsTab.getContent()).getCenter();
            tabs.getSelectionModel().selectLast(); root.applyCss(); root.layout(); snapshotRoot(smokeOutput.resolveSibling("bright-stats-bootstrap.png"));
            Path savedProject=smokeOutput.resolveSibling("bootstrap-project.json"); Files.writeString(savedProject,new GsonBuilder().serializeNulls().setPrettyPrinting().create().toJson(projectDocument()));
            load(JsonParser.parseString(Files.readString(savedProject)).getAsJsonObject(),"Reopened bootstrap project");
            if(!bootstrapOptions.equals(options))throw new AssertionError("Project lost bootstrap settings");
            displayReport(reopened); root.applyCss(); root.layout();
            // Exercise cancellation through the actual footer button; an interrupted run must not retain an archive.
            bootstrapOptions=new Bootstrap.Options(100000,42,.95); startBootstrap(null);
            Task<?> cancelled=activeTask;
            cancelled.addEventHandler(javafx.concurrent.WorkerStateEvent.WORKER_STATE_CANCELLED,event -> Platform.runLater(() -> {
                try {
                    if(lastReport!=null || !cancelCalculation.isDisabled() || sidebar.isDisabled())throw new AssertionError("Cancellation did not restore the interface");
                    predictionOptions=PredictionDialog.smokeTest(stage);startPrediction(()->finishPredictionSmoke(panels,iterations));
                }catch(Throwable error){fail(error);}
            }));
            cancelCalculation.fire();
        }catch(Throwable error){fail(error);}
    }
