    private void snapshotRoot(Path path) throws Exception {
        var image=root.snapshot(null,null); BufferedImage bitmap=new BufferedImage((int)image.getWidth(),(int)image.getHeight(),BufferedImage.TYPE_INT_ARGB);
        for(int y=0;y<bitmap.getHeight();y++)for(int x=0;x<bitmap.getWidth();x++)bitmap.setRGB(x,y,image.getPixelReader().getArgb(x,y));
        ImageIO.write(bitmap,"png",path.toFile());
    }
